// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"saccharomyces-boulardii":{"wirkmechanismus":"Unterstützt die Darmflora und hilft dem Darm, sich von Durchfall zu erholen. Die lebende Hefe übersteht die Magenpassage, siedelt sich vorübergehend im Darm an und wird nach dem Absetzen innert 2 bis 5 Tagen wieder ausgeschieden. Sie hemmt das Wachstum krankmachender Keime, baut bakterielle Giftstoffe ab (z. B. die Toxine von Clostridioides difficile) und stärkt die Darmschleimhaut sowie die örtliche Immunabwehr (sekretorisches IgA). Sie wird nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Hautausschlag, Quincke-Ödem)","Fungämie (Hefe im Blut) bei Patienten mit zentralem Venenkatheter, schwer Kranken oder Immungeschwächten"],"unbekannt":["Anaphylaxie (allergischer Schock)","Blähungen","Verstopfung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Keine ausreichenden Erfahrungen; nur nach Rücksprache anwenden.","hinweise":["Nicht zusammen mit sehr heissen (über 50 °C) oder eisgekühlten Speisen und Getränken oder mit Alkohol einnehmen – die Hefe ist lebend.","Bei Durchfall genügend Flüssigkeit und Salze ersetzen, besonders bei Kindern und älteren Menschen.","Bei Antibiotika-Behandlung kann die Hefe gleichzeitig eingenommen werden; Pilzmittel heben die Wirkung dagegen auf."],"darreichung":["Kapseln","Pulver zum Einnehmen (Beutel)"]},"sacituzumab-govitecan":{"wirkmechanismus":"Bringt ein Zellgift gezielt in Tumorzellen. Sacituzumab Govitecan besteht aus einem Antikörper gegen Trop-2, ein Oberflächenprotein vieler Brusttumoren, und SN-38, dem aktiven Abbauprodukt von Irinotecan. Nach Bindung und Aufnahme in die Zelle – teilweise auch in deren Umgebung – wird SN-38 freigesetzt, hemmt die Topoisomerase I und verursacht DNA-Strangbrüche, die zum Zelltod führen. SN-38 wird über das Enzym UGT1A1 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an Abwehrzellen), Anämie, Leukopenie","Durchfall, Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen","Alopezie (Haarausfall)","Müdigkeit, Appetitlosigkeit","Hypokaliämie, Hypomagnesiämie (Kalium-, Magnesiummangel)","Harnwegs- und Atemwegsinfekte","Kopfschmerzen, Schlaflosigkeit","Hautausschlag, Juckreiz"],"haeufig":["Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Sepsis (Blutvergiftung), Lungenentzündung","Überempfindlichkeits- und Infusionsreaktionen","Dehydratation (Flüssigkeitsmangel)","Kolitis (Darmentzündung)","Hypotonie (tiefer Blutdruck)"]},"schwangerschaft":"Kann das Ungeborene schädigen (enthält ein Zellgift); in der Schwangerschaft nicht anwenden. Frauen verhüten während und 6 Monate, Männer 3 Monate nach der letzten Dosis.","stillzeit":"Während und 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Bei Durchfall sofort mit der verordneten Behandlung (z. B. Loperamid) beginnen und viel trinken; bei anhaltendem Durchfall, Fieber oder Schwindel sofort melden.","Fieber über 38 °C sofort melden (Neutropenie).","Vor jeder Infusion werden Medikamente gegen Übelkeit und Infusionsreaktionen gegeben."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"sacubitril-valsartan":{"wirkmechanismus":"Entlastet das geschwächte Herz, indem es körpereigene Schutzhormone verstärkt und gleichzeitig das gefässverengende Angiotensin II blockiert. Sacubitril ist ein Prodrug; sein Wirkmetabolit Sacubitrilat (LBQ657) hemmt das Enzym Neprilysin, das natriuretische Peptide (ANP, BNP) abbaut. Diese Peptide erweitern die Gefässe, fördern die Ausscheidung von Salz und Wasser und wirken krankhaften Umbauvorgängen am Herzmuskel entgegen. Valsartan blockiert den Angiotensin-II-Rezeptor Typ 1 (AT1) und verhindert so die schädliche Aktivierung des Renin-Angiotensin-Aldosteron-Systems. Weil Neprilysin auch Bradykinin abbaut, darf die Kombination nicht mit ACE-Hemmern gegeben werden (Angioödem-Gefahr).","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium)","Hypotonie (tiefer Blutdruck)","Nierenfunktionsstörung"],"haeufig":["Schwindel, Kopfschmerzen, Synkope (kurze Ohnmacht), Vertigo (Drehschwindel)","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Nierenversagen, auch akut","Hypokaliämie (tiefes Kalium), Hypoglykämie (Unterzuckerung)","Anämie (Blutarmut)","Husten","Durchfall, Übelkeit, Gastritis (Magenschleimhautentzündung)","Müdigkeit, Asthenie (Schwäche)"],"gelegentlich":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Überempfindlichkeitsreaktionen","Juckreiz, Hautausschlag","Schwindel beim Lagewechsel"],"selten":["Halluzinationen","Schlafstörungen"],"sehrSelten":["Paranoia (Verfolgungswahn)"],"unbekannt":["Angioödem des Darms (Bauchschmerzen, Übelkeit, Erbrechen, Durchfall)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung des Ungeborenen wie bei allen RAAS-Hemmern). Bei festgestellter Schwangerschaft sofort ärztlich umstellen.","stillzeit":"Nicht anwenden – Übergang in die Muttermilch und Risiken für den Säugling können nicht ausgeschlossen werden.","hinweise":["Beim Wechsel von einem ACE-Hemmer diesen mindestens 36 Stunden vorher absetzen; keinen zusätzlichen ACE-Hemmer oder anderes Sartan einnehmen.","Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen sofort absetzen und Notfallhilfe holen.","Blutdruck, Kalium und Nierenwerte regelmässig kontrollieren; als Herzschwäche-Laborwert eignet sich NT-proBNP, nicht BNP (BNP steigt unter der Behandlung an).","Zweimal täglich einnehmen, mit oder ohne Essen; zu Beginn Schwindel möglich (Vorsicht beim Autofahren)."],"darreichung":["Filmtabletten"]},"safinamid":{"wirkmechanismus":"Verlängert die Wirkung von Dopamin im Gehirn. Safinamid hemmt hoch selektiv und reversibel die Monoaminoxidase B (MAO-B) und erhöht so die Dopaminkonzentration im Striatum. Zusätzlich blockiert es spannungsabhängige Natriumkanäle und vermindert die Freisetzung des erregenden Botenstoffs Glutamat.","nebenwirkungen":{"haeufig":["Schlaflosigkeit","Dyskinesien (unwillkürliche Überbewegungen)","Schläfrigkeit, Schwindel, Kopfschmerzen","Verschlechterung der Parkinson-Beschwerden","Katarakt (Grauer Star)","Blutdruckabfall beim Aufstehen","Übelkeit","Stürze"],"gelegentlich":["Halluzinationen, Depression, Angst, Verwirrtheit, ungewöhnliche Träume","Herzklopfen, Bluthochdruck","Verschwommenes Sehen, Doppelbilder","Verstopfung, Mundtrockenheit, Verdauungsbeschwerden","Gewichtsabnahme, Appetitverlust","Kribbeln, Zittern, Nervenschäden (Neuropathie)"],"selten":["Impulskontrollstörungen, Zwangsgedanken","Plötzliches Einschlafen"]},"schwangerschaft":"Nicht anwenden; Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Nicht stillen (im Tierversuch Übertritt in die Milch und Schäden bei Jungtieren).","hinweise":["Einmal täglich, unabhängig vom Essen einnehmen.","Keine Erkältungs- oder Hustenmittel mit Pseudoephedrin oder Dextromethorphan ohne Rücksprache einnehmen.","Plötzliches Einschlafen möglich – dann nicht Auto fahren; Sehveränderungen melden."],"darreichung":["Filmtabletten"]},"saegepalmenfruechte-extrakt":{"wirkmechanismus":"Pflanzlicher Extrakt, der die Beschwerden beim Wasserlassen lindert, ohne die Prostata zu verkleinern. Der Wirkmechanismus des fettlöslichen Extrakts aus Sägepalmenfrüchten ist nicht vollständig geklärt. In Laborversuchen hemmt er unter anderem die 5-Alpha-Reduktase und die Bindung von Androgenen und wirkt entzündungs- und wachstumshemmend auf Prostatazellen.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Magenschmerzen)","Überempfindlichkeitsreaktionen (z. B. Hautausschlag)"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Mit oder nach einer Mahlzeit einnehmen; das vermindert Magenbeschwerden.","Die Wirkung setzt erst nach einigen Wochen ein; die Prostata wird nicht verkleinert.","Regelmässige ärztliche Kontrollen der Prostata sind auch während der Behandlung nötig."],"darreichung":["Kapseln"]},"salbutamol":{"wirkmechanismus":"Erweitert innert Minuten verengte Bronchien und erleichtert das Atmen. Salbutamol stimuliert selektiv Beta-2-Rezeptoren der Bronchialmuskulatur; über einen Anstieg von cAMP erschlafft die glatte Muskulatur. Die Wirkung beginnt nach wenigen Minuten und hält etwa 4–6 Stunden an. Auf die Entzündung der Atemwege bei Asthma hat es keinen Einfluss.","nebenwirkungen":{"haeufig":["Zittern (Tremor)","Kopfschmerzen","Beschleunigter Puls (Tachykardie)"],"gelegentlich":["Herzklopfen","Reizung von Mund und Rachen","Muskelkrämpfe"],"selten":["Hypokaliämie (Kaliummangel)","Erweiterung der Blutgefässe mit Hautrötung"],"sehrSelten":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht, Blutdruckabfall, Kollaps)","Paradoxer Bronchospasmus","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Hyperaktivität"],"unbekannt":["Myokardischämie (Durchblutungsstörung des Herzmuskels)","Laktatazidose bei sehr hohen Dosen (z. B. Vernebler im Spital)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Salbutamol geht wahrscheinlich in die Muttermilch über; Anwendung nach ärztlicher Abwägung.","hinweise":["Dosieraerosol vor Gebrauch schütteln; mit Inhalierhilfe (Spacer) gelangt mehr Wirkstoff in die Lunge – Inhalationstechnik in der Apotheke zeigen lassen.","Wird das Spray häufiger als gewohnt gebraucht, ist das Asthma nicht ausreichend kontrolliert – ärztlich abklären lassen.","Bei Asthma ersetzt Salbutamol keine entzündungshemmende Basistherapie mit inhalativem Kortison."],"darreichung":["Dosieraerosol","Pulverinhalator","Inhalationslösung (Vernebler)"]},"salicylsaeure":{"wirkmechanismus":"Löst verhornte Haut- und Schuppenschichten auf. Salicylsäure lockert in der Hornschicht den Zusammenhalt der Hornzellen (Keratolyse), sodass Schuppen und Hornhaut abgelöst werden. Dadurch dringen gleichzeitig aufgetragene Wirkstoffe wie Kortison oder Fluorouracil besser in die Haut ein. Zusätzlich wirkt sie schwach antibakteriell und pilzhemmend.","nebenwirkungen":{"unbekannt":["Hautreizung, Brennen, Rötung oder Trockenheit an der Anwendungsstelle","Weissliche Verfärbung und Aufweichen der Haut um die behandelte Stelle","Allergische Kontaktdermatitis","Salicylatvergiftung bei grossflächiger Anwendung (Ohrensausen, Übelkeit, Schwindel, beschleunigte Atmung)"]},"schwangerschaft":"Kleinflächige, kurzfristige Anwendung nach ärztlicher Rücksprache möglich; grossflächige oder langdauernde Anwendung vermeiden. Warzenmittel mit Fluorouracil (Verrumal) sind kontraindiziert.","stillzeit":"Kleinflächig nach ärztlicher Rücksprache möglich; nicht im Brustbereich auftragen. Verrumal ist in der Stillzeit kontraindiziert.","hinweise":["Gesunde Haut um die behandelte Stelle schützen (z. B. mit Zinkpaste) und nur die betroffene Stelle behandeln.","Kortisonhaltige Kombination nicht langfristig, grossflächig oder unter luftdichten Verbänden anwenden.","Bei Kombinationspräparaten die Gegenanzeigen des Partnerwirkstoffs beachten – Verrumal (Fluorouracil) z. B. nicht zusammen mit dem Herpesmittel Brivudin anwenden.","Nicht in die Augen bringen."],"darreichung":["Salbe","Lösung zum Auftragen"]},"salmeterol":{"wirkmechanismus":"Hält die Bronchien etwa 12 Stunden lang offen. Salmeterol ist ein selektiver Beta-2-Agonist mit einer langen, fettlöslichen Seitenkette, die nahe am Rezeptor verankert bleibt und ihn wiederholt aktiviert; über einen Anstieg von cAMP erschlafft die Bronchialmuskulatur. Die Wirkung setzt erst nach 10–20 Minuten ein, deshalb ist es nicht für akute Atemnot geeignet. Gegen die Entzündung der Atemwege wirkt es nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Zittern (Tremor)","Herzklopfen","Muskelkrämpfe"],"gelegentlich":["Hautausschlag","Nervosität","Beschleunigter Puls (Tachykardie)"],"selten":["Hypokaliämie (Kaliummangel)","Schlaflosigkeit"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem","Hyperglykämie (erhöhter Blutzucker)","Herzrhythmusstörungen (Vorhofflimmern, supraventrikuläre Tachykardie, Extrasystolen)","Paradoxer Bronchospasmus","Reizung von Mund und Rachen","Gelenkschmerzen, unspezifische Brustschmerzen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nicht bei akuter Atemnot verwenden – dafür immer ein rasch wirksames Spray (z. B. Salbutamol) mitführen.","Bei Asthma immer zusammen mit einem inhalativen Kortison anwenden, am einfachsten als Kombinationspräparat.","Regelmässig zweimal täglich anwenden, auch wenn keine Beschwerden bestehen."],"darreichung":["Dosieraerosol","Pulverinhalator"]},"salmeterol-fluticason":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer lang anhaltenden bronchienerweiternden Wirkung. Fluticasonpropionat ist ein Glukokortikoid, das in der Bronchialschleimhaut die Bildung von Entzündungsstoffen und die Überempfindlichkeit der Atemwege vermindert. Salmeterol stimuliert Beta-2-Rezeptoren der Bronchialmuskulatur und hält die Atemwege etwa 12 Stunden offen. Gemeinsam senken sie die Zahl der Asthmaanfälle bzw. COPD-Verschlechterungen.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasen-Rachen-Entzündung (Nasopharyngitis)"],"haeufig":["Pilzinfektion in Mund und Rachen (Soor)","Heiserkeit, Rachenreizung","Lungenentzündung (bei COPD)","Bronchitis, Nebenhöhlenentzündung","Hypokaliämie (Kaliummangel)","Muskelkrämpfe, Gelenk- und Muskelschmerzen","Prellungen, Knochenbrüche nach Unfällen"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut, Atemnot","Katarakt (Grauer Star)","Hyperglykämie (erhöhter Blutzucker)","Angst, Schlafstörungen","Zittern, Herzklopfen, beschleunigter Puls","Vorhofflimmern, Angina pectoris"],"selten":["Anaphylaxie, Angioödem, paradoxer Bronchospasmus","Cushing-Syndrom, Unterdrückung der Nebennierenfunktion, Wachstumsverzögerung bei Kindern, verminderte Knochendichte","Glaukom (Grüner Star)","Verhaltensänderungen (Hyperaktivität, Reizbarkeit), vor allem bei Kindern","Herzrhythmusstörungen (supraventrikuläre Tachykardie, Extrasystolen)","Pilzinfektion der Speiseröhre"],"unbekannt":["Depression, Aggressivität","Verschwommenes Sehen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung und in der niedrigsten wirksamen Dosis; ein gut kontrolliertes Asthma ist für Mutter und Kind wichtig.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Nach jeder Inhalation den Mund mit Wasser ausspülen und ausspucken – das beugt Soor und Heiserkeit vor.","Regelmässig anwenden, auch ohne Beschwerden; für akute Atemnot ein rasch wirkendes Spray mitführen.","Nicht abrupt absetzen; Dosisänderungen nur nach ärztlicher Rücksprache.","Eine Ritonavir- oder Cobicistat-haltige HIV-Therapie vor Behandlungsbeginn ärztlich angeben."],"darreichung":["Pulverinhalator","Dosieraerosol"]},"sapropterin":{"wirkmechanismus":"Hilft dem geschwächten Enzym, das die Aminosäure Phenylalanin abbaut, wieder besser zu arbeiten. Sapropterin ist eine synthetische Form von Tetrahydrobiopterin (BH4), dem natürlichen Cofaktor der Phenylalaninhydroxylase, die Phenylalanin in Tyrosin umwandelt. Bei Phenylketonurie mit Restaktivität des Enzyms steigert BH4 dessen Aktivität und Stabilität; bei BH4-Mangel ersetzt es den fehlenden Cofaktor. Nicht alle Betroffenen sprechen an, deshalb wird das Ansprechen zu Beginn getestet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schnupfen (Rhinorrhö)"],"haeufig":["Halsschmerzen, verstopfte Nase, Husten","Durchfall, Erbrechen, Übelkeit","Bauchschmerzen, Verdauungsbeschwerden","Zu tiefer Phenylalaninspiegel (Hypophenylalaninämie)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Hautausschlag","Gastritis und Ösophagitis (Magen- und Speiseröhrenentzündung)"]},"schwangerschaft":"Nur anwenden, wenn eine strenge Diät den Phenylalaninspiegel nicht ausreichend senkt; ein zu hoher Phenylalaninspiegel der Mutter schädigt das Ungeborene.","stillzeit":"Nicht anwenden.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen, möglichst immer zur gleichen Tageszeit; Tabletten bzw. Pulver in Wasser oder Apfelsaft auflösen.","Die phenylalaninarme Diät nur nach Rücksprache mit dem Stoffwechselzentrum ändern.","Phenylalanin- und Tyrosinspiegel im Blut regelmässig kontrollieren lassen."],"darreichung":["Tabletten zur Herstellung einer Lösung zum Einnehmen","Pulver zur Herstellung einer Lösung zum Einnehmen"]},"sarilumab":{"wirkmechanismus":"Dämpft die Gelenkentzündung, indem es das Signal des Botenstoffs Interleukin-6 unterbricht. Sarilumab ist ein humaner monoklonaler IgG1-Antikörper, der an lösliche und membrangebundene Interleukin-6-Rezeptoren bindet und so die IL-6-vermittelte Signalübertragung hemmt. Dadurch sinken Entzündungswerte wie CRP, und Gelenkschwellung, Schmerzen und Gelenkzerstörung werden vermindert.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen)"],"haeufig":["Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung","Harnwegsinfekte","Lippenherpes (Herpes labialis)","Thrombozytopenie (Mangel an Blutplättchen)","Erhöhtes Cholesterin und erhöhte Triglyceride","Erhöhte Leberwerte (Transaminasen)","Rötung und Juckreiz an der Einstichstelle"],"gelegentlich":["Lungenentzündung","Zellulitis (bakterielle Hautinfektion)","Divertikulitis"],"unbekannt":["Magen-Darm-Perforation (meist als Komplikation einer Divertikulitis)","Tuberkulose und opportunistische Infektionen"]},"schwangerschaft":"Nur anwenden, wenn klar erforderlich. Frauen im gebärfähigen Alter sollen während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Sarilumab in die Muttermilch übergeht; über Stillen oder Behandlung entscheidet die Ärztin oder der Arzt.","hinweise":["Blutbild, Leberwerte und Blutfette werden vor Beginn und regelmässig während der Behandlung kontrolliert.","Fieber und CRP können trotz Infektion niedrig bleiben – bei Krankheitsgefühl früh ärztlich abklären.","Bei plötzlichen starken Bauchschmerzen, besonders mit Fieber, sofort ärztliche Hilfe holen (Darmdurchbruch)."],"darreichung":["Injektionslösung im Fertigpen oder in der Fertigspritze (unter die Haut)"]},"satralizumab":{"wirkmechanismus":"Beugt Entzündungsschüben an Sehnerv und Rückenmark vor, indem es den Entzündungsbotenstoff Interleukin-6 bremst. Satralizumab ist ein humanisierter monoklonaler IgG2-Antikörper, der an lösliche und membrangebundene Interleukin-6-Rezeptoren bindet und die IL-6-Signalübertragung hemmt. Interleukin-6 fördert bei NMOSD die Bildung der krankheitsauslösenden Aquaporin-4-Antikörper, die Durchlässigkeit der Blut-Hirn-Schranke und die Entzündung. Dank pH-abhängiger Bindung (Recycling-Antikörper) wirkt es lange, so dass nach der Einleitung eine Injektion alle 4 Wochen genügt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Gelenkschmerzen","Erhöhte Blutfette","Reaktionen bei der Injektion (Rötung, Juckreiz, Schmerz)"],"haeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Hautausschlag, Juckreiz","Migräne","Schlafstörungen","Periphere Ödeme (Wassereinlagerungen)","Erhöhte Leberwerte","Verminderung des Gerinnungseiweisses Fibrinogen"]},"schwangerschaft":"Erfahrungen begrenzt; vorsichtshalber vermeiden und nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob Satralizumab in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Startphase mit Injektionen in Woche 0, 2 und 4, danach alle 4 Wochen; nach Schulung ist die Selbstinjektion möglich.","Fieber und Entzündungswerte können trotz Infektion niedrig bleiben – bei Krankheitsgefühl früh ärztlich abklären.","Blutbild und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Injektionslösung in der Fertigspritze (unter die Haut)"]},"saxagliptin":{"wirkmechanismus":"Verstärkt die körpereigene Blutzuckerregulation nach den Mahlzeiten. Saxagliptin hemmt das Enzym Dipeptidylpeptidase-4 (DPP-4), das die Darmhormone GLP-1 und GIP (Inkretine) rasch abbaut. Die höheren Inkretinspiegel steigern blutzuckerabhängig die Insulinfreisetzung und hemmen die Glucagonausschüttung. Weil die Wirkung an erhöhte Blutzuckerwerte gebunden ist, verursacht Saxagliptin allein selten Unterzuckerungen. Es wird über CYP3A4/5 zu einem ebenfalls wirksamen Metaboliten abgebaut.","nebenwirkungen":{"haeufig":["Infektionen der oberen Atemwege, Sinusitis (Nasennebenhöhlenentzündung)","Harnwegsinfekte","Gastroenteritis (Magen-Darm-Infekt)","Kopfschmerzen","Erbrechen","Hypoglykämie (Unterzuckerung) in Kombination mit Sulfonylharnstoffen oder Insulin"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht)"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"],"unbekannt":["Bullöses Pemphigoid (blasenbildende Hauterkrankung)","Obstipation (Verstopfung)","Gelenkschmerzen"]},"schwangerschaft":"Nicht anwenden, da keine ausreichenden Erfahrungen vorliegen; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht anwenden; es ist nicht bekannt, ob Saxagliptin in die Muttermilch übergeht.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen (evtl. mit Ausstrahlung in den Rücken) sofort ärztlich abklären lassen.","Blasen auf der Haut ärztlich melden.","Kombinationspräparate mit Metformin (Kombiglyze XR) oder Dapagliflozin (Qtern) haben zusätzlich die Gegenanzeigen dieser Wirkstoffe."],"darreichung":["Filmtabletten","Retardtabletten (Kombination mit Metformin)"]},"scopolamin":{"wirkmechanismus":"Dämpft die Weiterleitung von Signalen aus dem Gleichgewichtsorgan an das Brechzentrum und beugt so der Reisekrankheit vor. Scopolamin blockiert als tertiäres Amin Muskarinrezeptoren im Gehirn, unter anderem in den Vestibulariskernen und im Brechzentrum. Das Pflaster gibt den Wirkstoff gleichmässig über rund 72 Stunden durch die Haut ab, was die Nebenwirkungen im Vergleich zu Tabletten verringert. Wie Atropin hemmt es zudem Speichel- und Schweissbildung und erweitert die Pupille.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Schläfrigkeit (Somnolenz)","Verschwommenes Sehen, Akkommodationsstörungen, Pupillenerweiterung (auch einseitig nach Berühren des Auges mit Pflasterresten)","Lidreizung","Hautreizung an der Klebestelle"],"selten":["Gedächtnis- und Konzentrationsstörungen, Unruhe, Desorientierung, Verwirrtheit, Halluzinationen","Glaukomanfall (Anstieg des Augeninnendrucks)","Störungen beim Wasserlassen, Harnverhalt"],"sehrSelten":["Ausgedehnter Hautausschlag"],"unbekannt":["Entzugsbeschwerden nach Entfernen des Pflasters nach mehrtägiger Anwendung (Schwindel, Übelkeit, Erbrechen, Kopfschmerzen, Gleichgewichtsstörungen)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; in der Schwangerschaft nur nach ärztlicher Abwägung anwenden.","stillzeit":"Scopolamin geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Pflaster am Vorabend oder spätestens 5–6 Stunden vor Reiseantritt auf saubere, unbehaarte Haut hinter dem Ohr kleben; wirkt bis zu 72 Stunden.","Nach dem Aufkleben oder Entfernen gründlich die Hände waschen: Wirkstoff in den Augen erweitert die Pupille und stört das Sehen.","Kann müde machen und das Sehen beeinträchtigen: nicht selbst Auto fahren oder Maschinen bedienen; Alkohol meiden.","Vor einer MRI-Untersuchung entfernen (Pflaster enthält Metall)."],"darreichung":["Transdermales Pflaster"]},"sebelipase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das Cholesterinester und Triglyceride in den Zellen abbaut. Sebelipase alfa ist eine gentechnisch im Eiklar transgener Hühner hergestellte menschliche lysosomale saure Lipase. Sie wird über Mannose- und Mannose-6-Phosphat-Rezeptoren vor allem von Leberzellen und Makrophagen aufgenommen und spaltet in den Lysosomen Cholesterinester und Triglyceride. Dadurch sinken Leberfett, Leberwerte und LDL-Cholesterin; bei schwer betroffenen Säuglingen verbessert sich das Überleben.","nebenwirkungen":{"sehrHaeufig":["Bei Säuglingen: infusionsbedingte Reaktionen mit Fieber, Schüttelfrost, Unruhe, Herzrasen, Atembeschwerden, Ausschlag, Nesselsucht oder Erbrechen"],"haeufig":["Überempfindlichkeitsreaktionen, auch Anaphylaxie und Kehlkopfschwellung","Schwindel","Herzrasen","Atemnot","Durchfall, Bauchschmerzen, Blähbauch, Übelkeit","Nesselsucht, Ausschlag, Juckreiz","Schüttelfrost, Fieber, Brustbeschwerden, Müdigkeit"]},"schwangerschaft":"Keine Erfahrungen. Vorsichtshalber möglichst nicht anwenden; nur nach strenger ärztlicher Abwägung.","stillzeit":"Keine Daten zum Übergang in die Muttermilch. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird als Infusion in eine Vene gegeben, bei Säuglingen wöchentlich, sonst meist alle 2 Wochen.","Eine Allergie gegen Ei vor Behandlungsbeginn unbedingt angeben.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"secukinumab":{"wirkmechanismus":"Bremst Entzündungen in Haut, Gelenken und Wirbelsäule. Secukinumab ist ein humaner monoklonaler IgG1-Antikörper, der den Botenstoff Interleukin-17A bindet und neutralisiert. IL-17A treibt bei Psoriasis und Spondyloarthritis die Entzündung und die übermässige Vermehrung von Hautzellen an; seine Blockade lässt Hautplaques und Gelenkentzündung zurückgehen.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (Erkältung, Nasen-Rachen-Entzündung)"],"haeufig":["Lippenherpes (oraler Herpes simplex)","Fusspilz (Tinea pedis)","Kopfschmerzen","Schnupfen","Durchfall, Übelkeit","Müdigkeit"],"gelegentlich":["Orale Candidose (Mundsoor), Infektionen der unteren Atemwege, Gehörgangsentzündung","Neutropenie (Mangel an neutrophilen Granulozyten)","Konjunktivitis (Bindehautentzündung)","Chronisch entzündliche Darmerkrankung (neu oder verschlechtert)","Nesselsucht, dyshidrotisches Ekzem"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Exfoliative Dermatitis (grossflächige Hautabschälung)","Vaskulitis (Gefässentzündung)"],"unbekannt":["Pilzinfektionen von Haut und Schleimhäuten, auch der Speiseröhre","Pyoderma gangraenosum (geschwürige Hauterkrankung)"]},"schwangerschaft":"Vorsichtshalber während der Schwangerschaft vermeiden; Frauen im gebärfähigen Alter verhüten während und bis 20 Wochen nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist wahrscheinlich; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Vor Beginn auf Tuberkulose testen und den Impfstatus vervollständigen lassen.","Bei anhaltendem Durchfall mit Blut oder Bauchkrämpfen ärztlich abklären lassen (entzündliche Darmerkrankung).","Im Kühlschrank lagern, nicht schütteln."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen)"]},"seladelpar":{"wirkmechanismus":"Verringert die Gallensäurelast der Leber und dämpft die Entzündung der Gallengänge. Seladelpar aktiviert selektiv den Kernrezeptor PPAR-delta in Leber- und Immunzellen. Über den Botenstoff FGF21 wird so das Schlüsselenzym der Gallensäurebildung (CYP7A1) gehemmt, zudem werden Entzündungs- und Vernarbungsprozesse gedämpft. Die alkalische Phosphatase sinkt, und in Studien nahm auch der Juckreiz ab.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen","Übelkeit","Blähbauch (aufgetriebener Bauch)","Schwindel"],"unbekannt":["Knochenbrüche","Erhöhte Leberwerte"]},"schwangerschaft":"Keine ausreichenden Daten; nicht empfohlen.","stillzeit":"Nicht empfohlen, da keine Daten vorliegen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; Gallensäurebinder mindestens 4 Stunden zeitversetzt.","Neue Medikamente, besonders Pilzmittel wie Fluconazol, vorher mit Ärztin, Arzt oder Apotheke besprechen."],"darreichung":["Hartkapseln"]},"selegilin":{"wirkmechanismus":"Verlängert die Wirkung des Botenstoffs Dopamin im Gehirn. Selegilin hemmt irreversibel und in üblicher Dosis selektiv die Monoaminoxidase B (MAO-B), die Dopamin abbaut. Dadurch steigt die Dopaminkonzentration in den Basalganglien, und die Wirkung von Levodopa wird verstärkt und verlängert. Zu den Abbauprodukten gehören L-Methamphetamin und L-Amphetamin.","nebenwirkungen":{"haeufig":["Mundtrockenheit","Übelkeit","Schwindel","Schlafstörungen","Verstärkung von Levodopa-Nebenwirkungen: Dyskinesien (Überbewegungen), Unruhe, Halluzinationen, Verwirrtheit"],"unbekannt":["Herzrhythmusstörungen, Herzklopfen, Angina-pectoris-Beschwerden","Blutdruckabfall beim Aufstehen","Erhöhte Leberwerte","Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)","Hautreaktionen","Störungen beim Wasserlösen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nicht anwenden.","stillzeit":"Nicht anwenden; Selegilin kann zudem die Milchbildung hemmen.","hinweise":["Morgens oder auf Morgen und Mittag verteilt einnehmen, nicht abends (Schlafstörungen).","Keine Schnupfen-, Grippe- oder Hustenmittel mit Pseudoephedrin, Ephedrin oder Dextromethorphan ohne Rücksprache einnehmen.","Vor jedem neuen Antidepressivum oder Schmerzmittel die Einnahme von Selegilin angeben."],"darreichung":["Tabletten"]},"selen":{"wirkmechanismus":"Selen ist ein Spurenelement, das als Bestandteil von Enzymen die Zellen vor oxidativen Schäden schützt und für den Schilddrüsenhormon-Stoffwechsel gebraucht wird. Natriumselenit wird im Körper in die Aminosäure Selenocystein eingebaut, das aktive Zentrum der Selenoproteine, z. B. der Glutathionperoxidasen, Thioredoxinreduktasen und Deiodasen. Die Spanne zwischen notwendiger und giftiger Dosis ist relativ eng.","nebenwirkungen":{"unbekannt":["Bei Überdosierung (Selenose): knoblauchartiger Atemgeruch, Müdigkeit, Übelkeit, Durchfall, Bauchschmerzen","Bei chronischer Überdosierung: Haarausfall, brüchige Nägel, Hautausschlag, Nervenstörungen"]},"schwangerschaft":"Bei nachgewiesenem Mangel in angemessener Dosis nach ärztlicher Abwägung möglich; eine Überdosierung ist zu vermeiden.","stillzeit":"Selen geht in die Muttermilch über; nur bei nachgewiesenem Mangel und nach ärztlicher Abwägung.","hinweise":["Nicht gleichzeitig mit Vitamin C einnehmen.","Ohne ärztliche Rücksprache keine zusätzlichen selenhaltigen Nahrungsergänzungsmittel einnehmen."],"darreichung":["Lösung zum Einnehmen","Injektionslösung"]},"selexipag":{"wirkmechanismus":"Erweitert die Blutgefässe der Lunge und bremst deren krankhaften Umbau. Selexipag ist kein Prostaglandin, sondern ein selektiver Agonist am Prostacyclin-Rezeptor (IP-Rezeptor). Es wird zu einem rund 37-mal stärker wirksamen aktiven Metaboliten umgewandelt, der den Grossteil der Wirkung trägt. Die Aktivierung des IP-Rezeptors entspannt die Gefässmuskulatur und hemmt deren Wucherung.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Flush (Hautrötung mit Hitzegefühl)","Durchfall, Übelkeit, Erbrechen","Kieferschmerzen","Muskel-, Gelenk- und Gliederschmerzen","Nasen-Rachen-Entzündung"],"haeufig":["Anämie (Blutarmut)","Schilddrüsenüberfunktion","Appetitlosigkeit, Gewichtsabnahme","Hypotonie (niedriger Blutdruck)","Verstopfte Nase","Bauchschmerzen","Hautausschlag, Nesselsucht, Hautrötung"],"gelegentlich":["Sinustachykardie (beschleunigter Puls)"]},"schwangerschaft":"Nur begrenzte Daten; nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Die Einnahme mit einer Mahlzeit verbessert die Verträglichkeit; die Dosis wird zu Beginn schrittweise gesteigert.","Nicht eigenmächtig absetzen; nach einem Unterbruch von 3 Tagen oder mehr wird mit einer niedrigeren Dosis neu begonnen.","Neue Medikamente, z. B. Clopidogrel oder Gemfibrozil, vorher mit Ärztin, Arzt oder Apotheke besprechen."],"darreichung":["Filmtabletten"]},"selinexor":{"wirkmechanismus":"Hält tumorhemmende Eiweisse im Zellkern fest, sodass Myelomzellen absterben. Selinexor blockiert reversibel das Transportprotein Exportin 1 (XPO1), das Tumorsuppressor-Proteine wie p53 und andere wachstumsregulierende Eiweisse aus dem Zellkern ausschleust. Die Anreicherung dieser Proteine im Kern und die verminderte Bildung von Onkoproteinen (z. B. c-Myc, Cyclin D1) führen zu Zellzyklusstopp und Apoptose der Krebszellen.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie (Mangel an Blutplättchen), Neutropenie, Anämie","Übelkeit, Erbrechen, Durchfall, Verstopfung","Appetitlosigkeit, Gewichtsverlust","Müdigkeit, Schwäche, Fieber","Hyponatriämie (Natriummangel)","Schwindel, Geschmacksstörungen, Schlaflosigkeit","Infektionen der Atemwege, Lungenentzündung","Grauer Star (Katarakt), verschwommenes Sehen"],"haeufig":["Febrile Neutropenie, Blutungen","Sepsis (Blutvergiftung)","Flüssigkeitsmangel (Dehydratation), Kaliummangel, erhöhter Blutzucker","Verwirrtheit, Ohnmacht (Synkope)","Niedriger Blutdruck","Akutes Nierenversagen","Stürze"],"unbekannt":["Tumorlyse-Syndrom","Enzephalopathie (Hirnfunktionsstörung)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und mindestens 1 Woche nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Vorbeugend die verordneten Mittel gegen Übelkeit einnehmen; ausreichend trinken und essen.","Tabletten ganz schlucken, nicht zerkleinern oder kauen.","Bei Schwindel oder Verwirrtheit kein Fahrzeug lenken und keine Maschinen bedienen.","Regelmässige Kontrolle von Blutbild, Natrium und Körpergewicht; bei Sehverschlechterung Augenkontrolle."],"darreichung":["Filmtabletten"]},"selpercatinib":{"wirkmechanismus":"Blockiert ein Wachstumssignal, das durch eine RET-Genveränderung im Tumor dauerhaft eingeschaltet ist. Selpercatinib ist ein hochselektiver Hemmer der Rezeptor-Tyrosinkinase RET, auch ihrer Fusions- und Mutationsformen (z. B. M918T und V804-Resistenzmutationen). Andere Kinasen wie VEGFR werden kaum gehemmt. Selpercatinib gelangt ins Gehirn und wirkt auch bei Hirnmetastasen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Durchfall, Verstopfung, Übelkeit, Erbrechen, Bauchschmerzen","Bluthochdruck","Müdigkeit, Ödeme, Kopfschmerzen, Schwindel","Hautausschlag","Erhöhte Leberwerte (ALT, AST)","QT-Verlängerung im EKG","Blutungen, Mangel an Blutplättchen"],"haeufig":["Überempfindlichkeitsreaktionen (Fieber, Ausschlag, Gelenk- und Muskelschmerzen)"],"unbekannt":["Schwere Leberschäden","Hypothyreose (Schilddrüsenunterfunktion)","Chylöse Ergüsse (milchige Flüssigkeit in Brust- oder Bauchraum)","Tumorlyse-Syndrom","Epiphysenlösung bei Jugendlichen"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nicht anwenden, ausser bei zwingender Notwendigkeit. Frauen und Männer müssen während der Behandlung und mindestens 1 Woche danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens 1 Woche danach nicht stillen.","hinweise":["Zweimal täglich (etwa alle 12 Stunden) unzerkaut einnehmen; säurehemmende Mittel nur nach Anweisung (PPI: Selpercatinib mit einer Mahlzeit; H2-Blocker und Antazida mit zeitlichem Abstand).","Keine Grapefruit, kein Johanniskraut.","Leberwerte, Blutdruck und EKG werden regelmässig kontrolliert.","Jugendliche: Hüft- oder Knieschmerzen und Hinken sofort melden (Epiphysenlösung)."],"darreichung":["Hartkapseln"]},"selumetinib":{"wirkmechanismus":"Lässt die bei Neurofibromatose wachsenden Nerventumoren schrumpfen oder bremst ihr Wachstum. Bei Neurofibromatose Typ 1 fehlt das Eiweiss Neurofibromin, wodurch der RAS–RAF–MEK–ERK-Signalweg dauerhaft aktiv ist. Selumetinib hemmt selektiv und reversibel die Kinasen MEK1 und MEK2 und unterbricht damit diesen Wachstumsreiz.","nebenwirkungen":{"sehrHaeufig":["Erbrechen, Übelkeit, Durchfall, Bauchschmerzen","Stomatitis (Mundschleimhautentzündung)","Akneartiger Hautausschlag, trockene Haut, Juckreiz","Paronychie (Nagelbettentzündung)","Haarveränderungen (Ausdünnung, Aufhellung)","Müdigkeit, Fieber","Erhöhte CK- und Leberwerte, erniedrigtes Albumin"],"haeufig":["Abnahme der Herzleistung (verminderte Auswurffraktion)","Verschwommenes Sehen","Atemnot","Periphere Ödeme (Wassereinlagerungen), Gesichtsschwellung","Erhöhte Nierenwerte (Kreatinin)"],"gelegentlich":["Seröse Netzhautablösung (Ablösung des retinalen Pigmentepithels)","Netzhautvenenverschluss"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Während und bis mindestens 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Kapseln ganz mit Wasser schlucken, nicht kauen, öffnen oder auflösen; zweimal täglich im Abstand von etwa 12 Stunden.","Keine Vitamin-E-Präparate zusätzlich einnehmen; Grapefruitsaft meiden.","Regelmässige Kontrollen: Herzfunktion (Ultraschall), Augen, Haut, Leberwerte und CK."],"darreichung":["Hartkapseln"]},"semaglutid":{"wirkmechanismus":"Wirkt wie das körpereigene Darmhormon GLP-1: Semaglutid steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und dämpft über das Gehirn Appetit und Hungergefühl. Dank einer Fettsäure-Seitenkette bindet es stark an Albumin und hat eine Halbwertszeit von etwa einer Woche, deshalb wird es einmal wöchentlich gespritzt. In der Tablette (Rybelsus) schützt der Hilfsstoff SNAC den Wirkstoff im Magen und ermöglicht die Aufnahme über die Magenschleimhaut – daher die strengen Einnahmeregeln. In grossen Studien senkte Semaglutid bei Typ-2-Diabetes bzw. bei Übergewicht mit bestehender Herz-Kreislauf-Erkrankung das Risiko schwerer Herz-Kreislauf-Ereignisse.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen, Verstopfung, Bauchschmerzen (unter Wegovy sehr häufig, unter Ozempic häufig)","Kopfschmerzen und Müdigkeit (unter Wegovy)","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoff"],"haeufig":["Appetitminderung","Schwindel","Verdauungsbeschwerden, Gastritis, Reflux, Aufstossen, Blähungen","Gallensteine (Cholelithiasis)","Komplikationen einer diabetischen Retinopathie (Netzhautschaden) bei Typ-2-Diabetes","Haarausfall (unter Wegovy)","Erhöhte Lipase- und Amylasewerte"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhter Puls","Verzögerte Magenentleerung","Geschmacksstörung","Überempfindlichkeitsreaktionen","Reaktionen an der Injektionsstelle","Blutdruckabfall, Schwindel beim Aufstehen (unter Wegovy)"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["NAION (nicht-arteriitische anteriore ischämische Optikusneuropathie): Durchblutungsstörung des Sehnervs mit plötzlichem Sehverlust"],"unbekannt":["Darmverschluss (Ileus)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"]},"schwangerschaft":"Nicht anwenden: Tierversuche zeigten Fruchtschädigung. Wegen der langen Wirkdauer mindestens 2 Monate vor einer geplanten Schwangerschaft absetzen; bei Diabetes wird Insulin eingesetzt.","stillzeit":"Nicht anwenden: Semaglutid geht bei Tieren in die Milch über; bei Rybelsus gelangt zudem der Hilfsstoff SNAC in die Muttermilch.","hinweise":["Spritze (Ozempic, Wegovy) einmal pro Woche am gleichen Wochentag, unabhängig vom Essen; die Dosis wird zur besseren Verträglichkeit schrittweise gesteigert.","Rybelsus morgens nüchtern mit höchstens einem halben Glas Wasser (bis 120 ml) ganz schlucken und danach mindestens 30 Minuten nichts essen, trinken oder andere Tabletten einnehmen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen; bei Übelkeit, Erbrechen oder Durchfall ausreichend trinken.","Vor Operationen, Narkosen oder Magenspiegelungen die Behandlung angeben; bei plötzlicher Sehverschlechterung sofort ärztlich abklären."],"darreichung":["Injektionslösung im Fertigpen","Tabletten (Rybelsus)"]},"sennoside":{"wirkmechanismus":"Regt die Dickdarmbewegung an und hält Wasser im Darm zurück, wodurch der Stuhl weicher wird. Die Sennoside sind Anthranoid-Glykoside, die unverändert bis in den Dickdarm gelangen. Dort spalten Darmbakterien sie zum wirksamen Rheinanthron, das die Peristaltik beschleunigt, die Rückaufnahme von Wasser und Salzen hemmt und deren Ausscheidung in den Darm fördert. Die Wirkung setzt nach etwa 8–12 Stunden ein.","nebenwirkungen":{"unbekannt":["Bauchkrämpfe und Bauchschmerzen, besonders bei Reizdarm","Durchfall mit wässrigen Stühlen","Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Hautausschlag)","Harmlose gelbe oder rotbraune Verfärbung des Urins","Bei längerer Anwendung: Störungen des Wasser- und Salzhaushalts, besonders Kaliummangel","Bei längerer Anwendung: Eiweiss und Blut im Urin","Bei längerer Anwendung: harmlose Dunkelfärbung der Darmschleimhaut (Pseudomelanosis coli)"]},"schwangerschaft":"Wegen Hinweisen auf erbgutverändernde Wirkungen einzelner Anthranoide im Labor in der Schwangerschaft nicht empfohlen; zuerst Ernährungsmassnahmen und Quellstoffe versuchen.","stillzeit":"Geringe Mengen wirksamer Abbauprodukte gehen in die Muttermilch über; Anwendung nicht empfohlen.","hinweise":["Nicht länger als 1–2 Wochen ohne ärztlichen Rat anwenden.","Am besten abends einnehmen; die Wirkung tritt nach 8–12 Stunden ein. Ausreichend trinken.","Eine Verfärbung des Urins ist harmlos."],"darreichung":["Tabletten","Granulat","Tee"]},"serplulimab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, damit Abwehrzellen Krebszellen wieder bekämpfen. Serplulimab ist ein humanisierter IgG4-Antikörper, der an den Rezeptor PD-1 auf T-Zellen bindet und dessen Aktivierung durch die Liganden PD-L1 und PD-L2 blockiert. Tumoren nutzen diese Liganden, um T-Zellen abzuschalten; die Blockade stellt die Immunantwort gegen den Tumor wieder her.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie (Mangel an weissen Blutkörperchen)","Thrombozytopenie (Mangel an Blutplättchen)","Anämie (Blutarmut)","Haarausfall","Übelkeit, Erbrechen","Appetitlosigkeit"],"haeufig":["Hypothyreose, Hyperthyreose (Schilddrüsenunter- und -überfunktion)","Hautausschlag","Pneumonitis (nicht-infektiöse Lungenentzündung)","Erhöhte Leberwerte","Hyperglykämie (erhöhter Blutzucker)","Infusionsreaktionen","Febrile Neutropenie (Fieber bei Mangel an weissen Blutkörperchen)"],"unbekannt":["Kolitis (Dickdarmentzündung)","Hepatitis (Leberentzündung)","Nebenniereninsuffizienz","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Myokarditis (Herzmuskelentzündung)","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: IgG-Antikörper gehen über die Plazenta, und die PD-1-Blockade kann die Toleranz gegenüber dem Ungeborenen stören; die begleitende Chemotherapie schädigt das Ungeborene. Frauen im gebärfähigen Alter verhüten während der Behandlung und mehrere Monate danach gemäss ärztlicher Anweisung.","stillzeit":"Während der Behandlung und einige Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Fieber oder Infektzeichen während der Chemotherapie sofort melden.","Blutbild, Leber-, Nieren- und Schilddrüsenwerte sowie Blutzucker werden regelmässig kontrolliert.","Den Patientenausweis immer bei sich tragen."],"darreichung":["Infusionskonzentrat"]},"sertindol":{"wirkmechanismus":"Mildert psychotische Symptome wie Wahn und Halluzinationen. Sertindol blockiert Dopamin-D2-, Serotonin-5-HT2A- und Alpha-1-adrenerge Rezeptoren und wirkt bevorzugt auf dopaminerge Nervenzellen des limbischen Systems, weshalb Bewegungsstörungen selten sind. Es macht kaum müde. Zugleich blockiert es Kaliumkanäle des Herzens (hERG) und verlängert dadurch deutlich die QT-Zeit.","nebenwirkungen":{"haeufig":["Verstopfte Nase (Rhinitis)","Verminderte Samenergussmenge","Schwindel, Kribbeln (Parästhesien)","Mundtrockenheit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Gewichtszunahme, Wassereinlagerungen in den Beinen","Atemnot","QT-Verlängerung im EKG"],"gelegentlich":["Hyperglykämie (erhöhter Blutzucker)","Synkope (Ohnmacht)","Krampfanfälle","Spätdyskinesien (unwillkürliche Bewegungen)","Torsade de pointes (lebensgefährliche Herzrhythmusstörung)"],"unbekannt":["Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Venöse Thromboembolien (Blutgerinnsel)","Plötzlicher Herztod"]},"schwangerschaft":"Wegen fehlender Erfahrungen nicht anwenden. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Nicht stillen.","hinweise":["EKG vor Beginn, während der Dosissteigerung und danach regelmässig (etwa alle 3 Monate); Kalium und Magnesium kontrollieren.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztlich abklären lassen.","Die Dosis wird über Wochen langsam gesteigert; nach einer Pause von mehr als einer Woche wieder einschleichend beginnen."],"darreichung":["Filmtabletten"]},"sertralin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Angst und Zwänge, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Sertralin hemmt selektiv den Serotonin-Transporter und damit die Wiederaufnahme von Serotonin in die Nervenzelle; auf die Wiederaufnahme von Noradrenalin und Dopamin wirkt es nur schwach. Die Halbwertszeit beträgt etwa 26 Stunden; die volle Wirkung entwickelt sich über 2–4 Wochen.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit, Schläfrigkeit","Schwindel, Kopfschmerzen","Durchfall, Übelkeit, Mundtrockenheit","Ejakulationsstörungen","Müdigkeit"],"haeufig":["Angst, Unruhe, Nervosität, Albträume, Zähneknirschen","Verminderte Libido, Erektionsstörungen","Zittern, Kribbeln, erhöhte Muskelspannung, Konzentrations- und Geschmacksstörungen","Sehstörungen, Ohrgeräusche (Tinnitus)","Herzklopfen, Hitzewallungen, Gähnen","Bauchschmerzen, Erbrechen, Verstopfung, Verdauungsbeschwerden, Blähungen","Vermehrtes Schwitzen, Hautausschlag","Rücken-, Gelenk- und Muskelschmerzen, Brustschmerzen"],"gelegentlich":["Halluzinationen, Aggressivität, gehobene Stimmung","Migräne, Ohnmacht (Synkope)","Herzrasen, Bluthochdruck","Nasenbluten, Atemnot","Schluckbeschwerden","Nesselsucht, Juckreiz, Haarausfall, Hautblutungen (Purpura)","Harninkontinenz"],"selten":["Hyponatriämie (Natriummangel), inadäquate ADH-Sekretion (SIADH)","Krampfanfälle, Bewegungsstörungen","Serotoninsyndrom","QT-Verlängerung, Torsade de pointes","Schwere Leberfunktionsstörungen","Angioödem, schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Magen-Darm-Blutungen","Priapismus (Dauererektion), Milchfluss (Galaktorrhö)"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Mikroskopische Kolitis (chronischer wässriger Durchfall)","Nachblutungen nach der Geburt","Erhöhtes Risiko für Knochenbrüche"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Daten aus vielen Schwangerschaften zeigen kein erhöhtes Fehlbildungsrisiko. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Sertralin geht nur in geringen Mengen in die Muttermilch über und ist im Blut gestillter Kinder meist nicht nachweisbar; eine Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Einmal täglich morgens oder abends einnehmen, unabhängig von den Mahlzeiten.","Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken zu Beginn sofort ärztlich melden.","Nicht abrupt absetzen, sondern schrittweise reduzieren (Absetzsymptome).","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol und Grapefruitsaft meiden."],"darreichung":["Filmtabletten"]},"setmelanotid":{"wirkmechanismus":"Ersetzt ein fehlendes Sättigungssignal im Gehirn und vermindert so den krankhaften Hunger. Setmelanotid ist ein Peptid, das den Melanocortin-4-Rezeptor (MC4R) im Hypothalamus aktiviert. Bei Gendefekten im Leptin-Melanocortin-Signalweg stellt es die Signalübertragung wieder her, senkt Hunger und Nahrungsaufnahme und fördert die Gewichtsabnahme. Da es auch den Melanocortin-1-Rezeptor der Pigmentzellen anregt, dunkelt die Haut häufig nach.","nebenwirkungen":{"sehrHaeufig":["Dunklere Hautpigmentierung (Hyperpigmentierung)","Reaktionen an der Einstichstelle (Rötung, Juckreiz, Schwellung, Schmerz)","Übelkeit","Erbrechen","Kopfschmerzen"],"haeufig":["Durchfall","Bauchschmerzen","Müdigkeit","Schwindel","Juckreiz"],"unbekannt":["Spontane Erektionen und andere Störungen der sexuellen Erregung","Neue oder veränderte Muttermale (Nävi)","Depression, Suizidgedanken"]},"schwangerschaft":"Keine ausreichenden Daten; aus Vorsicht nicht anwenden (eine Gewichtsabnahme ist in der Schwangerschaft unerwünscht). Bei Eintritt einer Schwangerschaft die Behandlung ärztlich überprüfen.","stillzeit":"Nicht bekannt, ob Setmelanotid in die Muttermilch übergeht; Nutzen und Risiko ärztlich abwägen.","hinweise":["Einmal täglich zu Beginn des Tages unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen; Einstichstelle wechseln.","Vor Beginn und während der Behandlung die Haut regelmässig auf Muttermale und Pigmentveränderungen untersuchen lassen.","Stimmungsveränderungen oder Suizidgedanken sofort ärztlich melden.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall."],"darreichung":["Injektionslösung zur Anwendung unter die Haut"]},"sevelamer":{"wirkmechanismus":"Bindet Phosphat aus der Nahrung im Darm, sodass weniger davon ins Blut gelangt. Sevelamer ist ein nicht resorbierbares, vernetztes Poly(allylamin)-Polymer, dessen im Darm protonierte Aminogruppen Phosphat über Ionen- und Wasserstoffbrücken binden. Es enthält weder Calcium noch Metalle. Zusätzlich bindet es Gallensäuren und senkt dadurch das LDL-Cholesterin.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Schmerzen im Oberbauch","Verstopfung"],"haeufig":["Durchfall","Verdauungsbeschwerden (Dyspepsie)","Blähungen","Bauchschmerzen"],"sehrSelten":["Überempfindlichkeitsreaktionen"],"unbekannt":["Darmverschluss (Ileus), Darmdurchbruch","Magen-Darm-Blutungen, Darmgeschwüre, Kolitis, Darmnekrose","Kristallablagerungen in der Darmschleimhaut","Juckreiz, Hautausschlag"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; Erfahrungen beim Menschen fehlen. Die Aufnahme von Vitaminen und Folsäure kann vermindert sein.","stillzeit":"Wird nicht ins Blut aufgenommen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Zu den Mahlzeiten einnehmen; Tabletten ganz schlucken, nicht zerkauen oder zerbrechen.","Andere Medikamente, deren Wirkung wichtig ist, mindestens 1 Stunde vor oder 3 Stunden nach Sevelamer einnehmen.","Phosphatarme Ernährung beibehalten; bei starker Verstopfung oder Bauchschmerzen ärztlich melden."],"darreichung":["Filmtabletten","Pulver zur Herstellung einer Suspension zum Einnehmen"]},"sevofluran":{"wirkmechanismus":"Versetzt beim Einatmen rasch in einen tiefen Schlaf, in dem Schmerzreize nicht mehr wahrgenommen werden. Sevofluran ist ein halogenierter Ether, der die Erregungsübertragung im Zentralnervensystem dämpft, unter anderem durch Verstärkung hemmender GABA-A- und Glycin-Rezeptoren. Wegen seiner geringen Löslichkeit im Blut flutet es schnell an und ab, sodass Einschlafen und Aufwachen rasch erfolgen. Da es die Atemwege kaum reizt, eignet es sich besonders für die Narkoseeinleitung über eine Maske, etwa bei Kindern.","nebenwirkungen":{"sehrHaeufig":["Unruhe (Agitiertheit) beim Aufwachen","Bradykardie (langsamer Puls)","Hypotonie (Blutdruckabfall)","Husten","Übelkeit, Erbrechen"],"haeufig":["Schläfrigkeit, Schwindel, Kopfschmerzen","Tachykardie (Herzrasen), Blutdruckanstieg","Atemdepression, Atemwegsverlegung, Laryngospasmus (Stimmritzenkrampf)","Vermehrter Speichelfluss","Schüttelfrost, Fieber, Unterkühlung","Veränderte Blutzucker- und Leberwerte"],"gelegentlich":["Verwirrtheit","Herzrhythmusstörungen (z. B. AV-Block, Vorhofflimmern, Extrasystolen)","Atemstillstand (Apnoe), Sauerstoffmangel","Asthma-Anfall","Harnverhalt"],"unbekannt":["Maligne Hyperthermie","Krampfanfälle, unwillkürliche Bewegungen","QT-Verlängerung mit Torsade de pointes, Herzstillstand","Anaphylaxie (schwere allergische Reaktion)","Hepatitis, Leberversagen","Hyperkaliämie (erhöhtes Kalium)","Erhöhter Hirndruck"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; beim Kaiserschnitt wurde Sevofluran sicher angewendet. Es entspannt die Gebärmuttermuskulatur, was Blutungen verstärken kann.","stillzeit":"Der Übergang in die Muttermilch ist nicht untersucht; wegen der raschen Ausscheidung ist Stillen nach dem Aufwachen meist möglich – Vorgehen mit dem Narkoseteam besprechen.","hinweise":["Nach einer Narkose mindestens 24 Stunden nicht Auto fahren, keine Maschinen bedienen und keinen Alkohol trinken.","Dem Narkoseteam maligne Hyperthermie in der Familie, Muskelerkrankungen und frühere Narkoseprobleme unbedingt melden.","Einnahme von MAO-Hemmern oder Johanniskraut vor geplanten Eingriffen angeben."],"darreichung":["Flüssigkeit zur Herstellung eines Dampfs zur Inhalation"]},"silbersulfadiazin":{"wirkmechanismus":"Wirkt gegen Bakterien und Pilze auf Wunden, indem langsam Silber freigesetzt wird. Silbersulfadiazin gibt im Wundsekret Silberionen ab, die Zellmembran und Erbgut der Keime schädigen; das Sulfonamid Sulfadiazin hemmt zusätzlich die bakterielle Folsäurebildung. Wirksam ist es gegen viele grampositive und gramnegative Bakterien einschliesslich Pseudomonas sowie gegen Hefepilze. Bei grossflächiger Anwendung kann ein Teil des Sulfadiazins ins Blut gelangen.","nebenwirkungen":{"unbekannt":["Brennen, Schmerzen oder Juckreiz an der Wunde","Hautausschlag, allergische Hautreaktionen","Vorübergehende Leukopenie (Mangel an weissen Blutkörperchen)","Graue bis blaue Hautverfärbung (Argyrie) bei Langzeitanwendung","Hämolyse (Blutzerfall) bei G6PD-Mangel","Interstitielle Nephritis (Nierenentzündung)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Gegen Ende der Schwangerschaft kontraindiziert (Kernikterus beim Neugeborenen); sonst nur nach strenger ärztlicher Abwägung, vor allem bei grossflächiger Anwendung.","stillzeit":"Sulfonamide gehen in die Muttermilch über und können beim Säugling eine Gelbsucht verstärken – nur nach ärztlicher Abwägung und nicht im Brustbereich anwenden.","hinweise":["Creme mit sterilem Handschuh oder Spatel auf die gereinigte Wunde auftragen und die Wunde stets bedeckt halten.","Vor jeder neuen Anwendung Cremereste und Wundsekret mit Wasser oder Kochsalzlösung entfernen.","Bei grossflächiger Anwendung Blutbild und Nierenwerte kontrollieren lassen.","Nicht gleichzeitig mit enzymatischen Wundreinigern verwenden."],"darreichung":["Creme"]},"sildenafil":{"wirkmechanismus":"Verbessert die Durchblutung des Penis bei sexueller Erregung bzw. erweitert die Blutgefässe der Lunge. Sildenafil hemmt selektiv das Enzym Phosphodiesterase 5, das den Botenstoff cGMP abbaut. Bei sexueller Stimulation freigesetztes Stickstoffmonoxid (NO) erhöht cGMP in den Schwellkörpern; durch die Hemmung des Abbaus bleibt cGMP länger erhöht, die glatte Muskulatur entspannt sich und Blut strömt ein. In den Lungengefässen bewirkt derselbe Mechanismus eine Gefässerweiterung und senkt den Lungenarteriendruck.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall und Gliederschmerzen (bei Lungenhochdruck-Dosierung)"],"haeufig":["Gesichtsrötung (Flush), Hitzewallungen","Verstopfte Nase","Verdauungsbeschwerden (Dyspepsie), Übelkeit","Schwindel","Sehstörungen: veränderte Farbwahrnehmung (Blau- oder Gelbstich), verschwommenes Sehen","Nasenbluten, Schlaflosigkeit, Muskelschmerzen (bei Lungenhochdruck-Dosierung)"],"gelegentlich":["Herzrasen, Herzklopfen","Blutdruckabfall oder Blutdruckanstieg","Augenschmerzen, Lichtempfindlichkeit, gerötete Augen","Ohrensausen (Tinnitus)","Schläfrigkeit","Erbrechen, Mundtrockenheit","Hautausschlag","Blut im Urin","Brustschmerzen, Müdigkeit"],"selten":["Herzinfarkt, Herzrhythmusstörungen, plötzlicher Herztod","Schlaganfall, TIA, Krampfanfälle, Ohnmacht","NAION (Durchblutungsstörung des Sehnervs mit Sehverlust), Netzhautgefässverschluss","Plötzlicher Hörverlust","Priapismus (schmerzhafte Dauererektion über 4 Stunden)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)"]},"schwangerschaft":"Bei Lungenhochdruck nur, wenn unbedingt erforderlich – es liegen keine ausreichenden Daten vor. Für Frauen ist die Behandlung von Erektionsstörungen nicht vorgesehen.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Bei Erektionsstörungen etwa 1 Stunde vor dem Geschlechtsverkehr einnehmen; eine fettreiche Mahlzeit verzögert den Wirkungseintritt. Höchstens einmal täglich.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall – sofort ärztliche Hilfe holen.","Niemals zusammen mit Nitraten oder «Poppers» (Amylnitrit) – lebensbedrohlicher Blutdruckabfall.","Bei plötzlicher Sehverschlechterung oder plötzlichem Hörverlust sofort absetzen und ärztlich abklären lassen."],"darreichung":["Filmtabletten","Schmelztabletten","Pulver für Suspension zum Einnehmen (Revatio)"]},"silodosin":{"wirkmechanismus":"Entspannt die Muskulatur in Prostata und Blasenhals und erleichtert so das Wasserlassen. Silodosin blockiert hochselektiv die Alpha-1A-Adrenozeptoren, die vor allem in Prostata, Blasengrund, Blasenhals und Harnröhre vorkommen. Dadurch sinkt der Widerstand für den Harnabfluss, und Beschwerden wie schwacher Harnstrahl oder häufiger Harndrang nehmen ab. Die Prostata wird dabei nicht verkleinert.","nebenwirkungen":{"sehrHaeufig":["Ejakulationsstörungen (verminderter oder fehlender Samenerguss, retrograde Ejakulation)"],"haeufig":["Schwindel","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Verstopfte Nase","Durchfall"],"gelegentlich":["Verminderte Libido, Erektionsstörung","Herzrasen","Blutdruckabfall","Übelkeit, Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Synkope (Ohnmacht), Bewusstlosigkeit","Herzklopfen"],"sehrSelten":["Allergische Reaktionen mit Schwellung von Gesicht, Zunge oder Rachen"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Operationen am grauen Star"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Täglich zur gleichen Zeit mit einer Mahlzeit einnehmen.","Zu Beginn kann beim Aufstehen Schwindel auftreten – langsam aufstehen und sich bei Schwindel hinsetzen.","Vor einer Operation am grauen Star die Einnahme angeben.","Ein verminderter oder fehlender Samenerguss ist häufig und nach dem Absetzen umkehrbar."],"darreichung":["Hartkapseln"]},"siltuximab":{"wirkmechanismus":"Bremst die krankhafte Vermehrung von Immunzellen in den Lymphknoten, die bei der Castleman-Krankheit durch zu viel Interleukin-6 angetrieben wird. Siltuximab ist ein chimärer (Mensch/Maus) monoklonaler IgG1κ-Antikörper, der Interleukin-6 bindet und dessen Andocken an lösliche und membranständige Interleukin-6-Rezeptoren verhindert. Dadurch gehen Lymphknotenvergrösserung, Fieber, Müdigkeit, Blutarmut und Entzündungswerte zurück.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung","Neutropenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Hautausschlag, Juckreiz","Erhöhte Triglyceride","Gewichtszunahme","Lokale Ödeme (Schwellungen)"],"haeufig":["Infusionsreaktionen","Erhöhtes Cholesterin","Verstopfung, Durchfall","Mundgeschwüre","Halsschmerzen"],"unbekannt":["Bluthochdruck","Bauchschmerzen","Erhöhte Harnsäure","Eingeschränkte Nierenfunktion","Magen-Darm-Perforation (Durchbruch)","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter sollen während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Übergang in die Muttermilch nicht bekannt; über Abstillen oder Therapieverzicht entscheidet die Ärztin oder der Arzt.","hinweise":["Infusion alle 3 Wochen in der Klinik; in den ersten 12 Monaten vor jeder Infusion Blutbildkontrolle.","Fieber und CRP können trotz Infektion niedrig bleiben – bei Krankheitsgefühl, Husten oder Brennen beim Wasserlösen früh ärztlich abklären.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Pulver zur Herstellung eines Konzentrats für eine Infusionslösung"]},"silymarin-mariendistel":{"wirkmechanismus":"Schützt die Leberzellen vor Giftstoffen und unterstützt ihre Erneuerung. Silymarin ist ein Gemisch von Flavonolignanen aus Mariendistelfrüchten, sein Hauptbestandteil ist Silibinin. Es stabilisiert die Zellmembranen der Leberzellen, fängt freie Radikale ab und regt die Eiweissbildung und damit die Regeneration der Leber an. Bei einer Knollenblätterpilzvergiftung hemmt Silibinin die Aufnahme des Pilzgifts Amanitin in die Leberzellen.","nebenwirkungen":{"unbekannt":["Leichte Magen-Darm-Beschwerden, leicht abführende Wirkung","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Atemnot)","Hitzegefühl (Flush) während der Silibinin-Infusion"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach ärztlicher Abwägung. Bei einer Knollenblätterpilzvergiftung überwiegt der Nutzen der Infusion.","stillzeit":"Keine ausreichenden Daten; nur nach ärztlicher Abwägung.","hinweise":["Bei Verdacht auf eine Pilzvergiftung sofort den Notruf 144 oder Tox Info Suisse (Telefon 145) kontaktieren – die Kapseln sind dafür nicht geeignet.","Klinisch bedeutsame Wechselwirkungen mit anderen Arzneimitteln sind nicht bekannt."],"darreichung":["Kapseln","Pulver zur Herstellung einer Infusionslösung (Silibinin)"]},"simeticon":{"wirkmechanismus":"Lässt Gasbläschen im Darm zerfallen, sodass das Gas leichter abgehen oder über die Darmwand aufgenommen werden kann. Simeticon ist eine Mischung aus Dimeticon (einem Silikonöl) und Siliciumdioxid, die die Oberflächenspannung der Schaumbläschen im Speisebrei herabsetzt; kleine Bläschen vereinigen sich zu grösseren Gasblasen. Es wirkt rein physikalisch, wird nicht ins Blut aufgenommen und unverändert mit dem Stuhl ausgeschieden.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen wie Hautausschlag oder Juckreiz"]},"schwangerschaft":"Kann angewendet werden, da Simeticon nicht ins Blut aufgenommen wird.","stillzeit":"Kann in der Stillzeit angewendet werden.","hinweise":["Nach den Mahlzeiten und bei Bedarf vor dem Schlafengehen einnehmen; Kautabletten gut kauen, Tropfen vor Gebrauch schütteln.","Bei Säuglingen können die Tropfen in den Schoppen gegeben oder vor dem Stillen mit einem Löffel verabreicht werden.","Bei Verschlucken von Spülmittel zusätzlich Tox Info Suisse unter Telefon 145 anrufen."],"darreichung":["Kautabletten","Tropfen (Suspension zum Einnehmen)"]},"simvastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Simvastatin ist ein Prodrug (Lacton), das in der Leber zur aktiven Beta-Hydroxysäure umgewandelt wird; diese hemmt die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden daraufhin mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut; zusätzlich sinken die Triglyceride leicht und das HDL-Cholesterin steigt etwas. Simvastatin wird vor allem über CYP3A4 abgebaut, deshalb sind Wechselwirkungen häufig und können zu Muskelschäden führen.","nebenwirkungen":{"selten":["Myopathie, Myositis (Muskelentzündung), Muskelschmerzen und -krämpfe","Rhabdomyolyse (Muskelzerfall), teils mit akutem Nierenversagen","Verstopfung, Bauchschmerzen, Blähungen, Verdauungsbeschwerden, Durchfall, Übelkeit, Erbrechen","Kopfschmerzen, Schwindel, Parästhesien (Kribbeln), periphere Neuropathie","Erhöhte Leberwerte und CK (Muskelenzym); Hepatitis, Gelbsucht","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hautausschlag, Juckreiz, Haarausfall; Überempfindlichkeitssyndrom (u. a. Angioödem, Gelenkbeschwerden, Fieber)","Anämie (Blutarmut), Schwäche"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Leberversagen, auch tödlich","Muskelriss","Gedächtnisstörungen, Schlaflosigkeit","Lichenoide Hautausschläge","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Tendinopathie (Sehnenschäden), teils mit Sehnenriss","Interstitielle Lungenerkrankung","Depression","Erektionsstörung","Myasthenia gravis (Muskelschwäche) oder deren Verschlechterung","Diabetes mellitus bei Personen mit Risikofaktoren"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Bei Eintritt einer Schwangerschaft sofort absetzen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Kontraindiziert – Übergang in die Muttermilch nicht bekannt, schwere Nebenwirkungen beim Säugling möglich.","hinweise":["Einmal täglich am Abend einnehmen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Grapefruitsaft meiden; neue Medikamente (v. a. Antibiotika, Pilzmittel, Herz- und HIV-Mittel) immer auf Wechselwirkungen prüfen lassen.","Leberwerte vor Behandlungsbeginn und bei Bedarf kontrollieren; Ernährung und Bewegung bleiben wichtig."],"darreichung":["Filmtabletten"]},"sinecatechine":{"wirkmechanismus":"Hilft dem Körper, Feigwarzen abzubauen; der genaue Wirkmechanismus ist nicht bekannt. Der Extrakt enthält vor allem Catechine wie Epigallocatechingallat (EGCG). In Laborversuchen wirken diese antioxidativ, hemmen das Wachstum aktivierter Hautzellen (Keratinozyten) und beeinflussen Entzündungsreaktionen. Eine direkte Wirkung gegen das Papillomavirus ist nicht nachgewiesen.","nebenwirkungen":{"sehrHaeufig":["Örtliche Reaktionen: Rötung, Juckreiz, Brennen und Schmerzen","Schwellung (Ödem) und Verhärtung an der Anwendungsstelle","Geschwüre und Bläschen an der Anwendungsstelle"],"haeufig":["Hautabschuppung, Nässen und leichte Blutungen an der Anwendungsstelle"],"gelegentlich":["Lymphknotenschwellung in der Leiste","Vorhautverengung (Phimose)","Örtliche Infektion","Hautausschlag"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Vorsichtshalber in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Bestandteile in die Muttermilch übergehen. Nur nach ärztlicher Abwägung anwenden.","hinweise":["Dreimal täglich dünn auf alle Warzen auftragen und vor der nächsten Anwendung nicht abwaschen; Behandlung höchstens 16 Wochen.","Während die Salbe auf der Haut ist, keinen Geschlechtsverkehr haben; die Salbe kann Kondome und Diaphragmen schwächen und Wäsche verfärben.","Behandelte Stellen nicht abdecken. Frauen, die Tampons benutzen, setzen den Tampon vor dem Auftragen ein."],"darreichung":["Salbe"]},"siponimod":{"wirkmechanismus":"Hält bestimmte weisse Blutkörperchen in den Lymphknoten zurück und vermindert so Entzündungen in Gehirn und Rückenmark. Siponimod bindet selektiv an die Sphingosin-1-Phosphat-Rezeptoren S1P1 und S1P5. Über S1P1 werden die Rezeptoren auf Lymphozyten internalisiert, so dass diese die Lymphknoten nicht mehr verlassen können. Da es ins Gehirn gelangt, wirkt es möglicherweise zusätzlich über S1P-Rezeptoren auf Stützzellen des Nervensystems. Abgebaut wird es hauptsächlich über CYP2C9, weshalb der Erbgut-Typ dieses Enzyms über Eignung und Dosis entscheidet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Bluthochdruck","Erhöhte Leberwerte"],"haeufig":["Gürtelrose (Herpes zoster)","Basalzellkarzinom (heller Hautkrebs), Muttermale","Lymphopenie (Mangel an Lymphozyten)","Schwindel, Zittern (Tremor)","Krampfanfälle","Makulaödem (Schwellung der Netzhautmitte)","Pulsverlangsamung (Bradykardie) und AV-Block","Übelkeit, Durchfall, periphere Ödeme"],"unbekannt":["PML (progressive multifokale Leukenzephalopathie)","Kryptokokken-Meningitis","Melanom und andere Hautkrebsarten","PRES (posteriores reversibles Enzephalopathie-Syndrom)","Schwere Verschlechterung der MS nach dem Absetzen"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und mindestens 10 Tage nach dem Absetzen zuverlässig verhüten.","stillzeit":"Nicht stillen während der Behandlung.","hinweise":["Vor Beginn wird der CYP2C9-Genotyp bestimmt; er entscheidet über Eignung und Erhaltungsdosis.","Einschleichende Dosierung über 5 Tage; nach einem Unterbruch von 4 oder mehr Tagen erneut einschleichen.","Augen, Haut, Blutdruck und Leberwerte regelmässig kontrollieren lassen; nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"sirolimus":{"wirkmechanismus":"Verhindert, dass sich Abwehrzellen nach einer Transplantation vermehren und das fremde Organ angreifen. Sirolimus bindet in den Zellen an das Protein FKBP12; dieser Komplex hemmt die Kinase mTOR (mammalian target of rapamycin). Dadurch wird die durch Interleukin-2 und andere Wachstumsfaktoren ausgelöste Zellteilung der T- und B-Lymphozyten in der G1-Phase blockiert. Anders als Calcineurin-Hemmer hemmt Sirolimus nicht die Bildung von Interleukin-2 selbst.","nebenwirkungen":{"sehrHaeufig":["Infektionen durch Bakterien, Viren und Pilze, u. a. Lungenentzündung und Harnwegsinfekte","Thrombozytopenie, Anämie, Leukopenie (Mangel an Blutplättchen, roten bzw. weissen Blutkörperchen)","Erhöhte Blutfette (Cholesterin, Triglyceride)","Hypokaliämie (Kaliummangel), Hypophosphatämie, erhöhter Blutzucker","Ödeme (Wassereinlagerungen), Lymphozele, Wundheilungsstörungen","Bluthochdruck, Kopfschmerzen","Durchfall, Verstopfung, Übelkeit, Bauchschmerzen","Akne, Hautausschlag, Gelenkschmerzen, Eiweiss im Urin"],"haeufig":["Mundgeschwüre (Stomatitis)","Nicht infektiöse Lungenentzündung (Pneumonitis), Pleuraerguss","Tiefe Venenthrombose, Lungenembolie","Hämolytisch-urämisches Syndrom (Gerinnsel in kleinen Gefässen)","Weisser Hautkrebs","Sepsis, Zytomegalie- und Herpes-zoster-Infektionen","Pankreatitis (Bauchspeicheldrüsenentzündung), Perikarderguss","Überempfindlichkeitsreaktionen inkl. Angioödem und Anaphylaxie"],"gelegentlich":["Lymphome und andere lymphoproliferative Erkrankungen nach Transplantation","Melanom","Nephrotisches Syndrom","Panzytopenie, thrombotisch-thrombozytopenische Purpura","Tuberkulose","Clostridioides-difficile-Darmentzündung"],"selten":["Alveolarproteinose (Eiweissablagerungen in den Lungenbläschen)"],"unbekannt":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Progressive multifokale Leukoenzephalopathie (PML)"]},"schwangerschaft":"Nur anwenden, wenn eindeutig erforderlich. Frauen müssen vor, während und bis 12 Wochen nach Ende der Behandlung zuverlässig verhüten.","stillzeit":"Nicht stillen.","hinweise":["Regelmässige Kontrollen von Talspiegel, Blutfetten, Nierenwerten, Urin-Eiweiss und Blutbild.","Immer gleich einnehmen – entweder stets mit oder stets ohne Essen; kein Grapefruitsaft. Bei Kombination mit Ciclosporin 4 Stunden Abstand einhalten.","Haut konsequent vor Sonne schützen und regelmässig kontrollieren lassen (erhöhtes Hautkrebsrisiko).","Keine Lebendimpfungen; neue Medikamente, auch pflanzliche wie Johanniskraut, immer mit der Transplantationsmedizin absprechen."],"darreichung":["Dragées (überzogene Tabletten)"]},"sitagliptin":{"wirkmechanismus":"Verstärkt die Wirkung körpereigener Darmhormone, die nach dem Essen die Insulinausschüttung anregen. Sitagliptin hemmt selektiv das Enzym Dipeptidylpeptidase-4 (DPP-4), das die Inkretine GLP-1 und GIP rasch abbaut; deren aktive Spiegel steigen dadurch auf das Zwei- bis Dreifache. Die Folge ist eine blutzuckerabhängige Steigerung der Insulinfreisetzung und eine geringere Glukagonausschüttung – bei normalem Blutzucker lässt die Wirkung nach, daher allein kaum Unterzuckerungen. Sitagliptin wird überwiegend unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung), vor allem in Kombination mit Sulfonylharnstoff oder Insulin","Kopfschmerzen","In Kombination mit Metformin: Übelkeit, Blähungen","In Kombination mit Pioglitazon: periphere Ödeme (Wassereinlagerungen)"],"gelegentlich":["Schwindel","Verstopfung","Juckreiz"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)"],"unbekannt":["Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie, Angioödem, Ausschlag, Nesselsucht und kutaner Vaskulitis","Schwere Hautreaktionen einschliesslich Stevens-Johnson-Syndrom","Bullöses Pemphigoid (blasenbildende Hauterkrankung)","Akute Pankreatitis, auch hämorrhagisch oder nekrotisierend mit tödlichem Verlauf","Interstitielle Lungenerkrankung","Gelenk-, Muskel- und Rückenschmerzen","Eingeschränkte Nierenfunktion, akutes Nierenversagen","Erbrechen"]},"schwangerschaft":"Nicht anwenden: Es liegen keine ausreichenden Erfahrungen vor; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht anwenden: Es ist nicht bekannt, ob Sitagliptin beim Menschen in die Muttermilch übergeht (bei Ratten ja).","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen, eventuell in den Rücken ausstrahlend, sofort ärztlich abklären lassen (mögliche Bauchspeicheldrüsenentzündung).","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen, da die Dosis davon abhängt.","Allein eingenommen kaum Unterzuckerungen; in Kombination mit Sulfonylharnstoff oder Insulin kann eine Unterzuckerung die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"sofosbuvir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-C-Virus in der Leber. Sofosbuvir ist ein Prodrug: In den Leberzellen entsteht daraus das aktive Uridin-Analogon-Triphosphat (GS-461203). Dieses wird von der viralen RNA-Polymerase NS5B in die neue Virus-RNA eingebaut und führt zum Kettenabbruch. Es wirkt gegen alle Genotypen und hat eine hohe Resistenzbarriere.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Reizbarkeit","Kopfschmerzen","Übelkeit","Schlaflosigkeit","Abfall des Hämoglobins und Bilirubinanstieg (v. a. durch das gleichzeitig gegebene Ribavirin)"],"haeufig":["Anämie (Blutarmut)","Verminderter Appetit","Depression, Konzentrationsstörungen","Atemnot, Husten","Bauchbeschwerden, Verstopfung, Verdauungsbeschwerden","Haarausfall, trockene Haut, Juckreiz","Gelenk-, Rücken- und Muskelschmerzen, Muskelkrämpfe","Fieber, Schwäche, verschwommenes Sehen"],"unbekannt":["Schwere Bradykardie und Herzblock bei gleichzeitiger Amiodaron-Einnahme","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; Anwendung nicht empfohlen. In Kombination mit Ribavirin kontraindiziert – sichere Verhütung während und nach der Therapie gemäss Ribavirin-Fachinformation.","stillzeit":"Nicht bekannt, ob Sofosbuvir beim Menschen in die Muttermilch übergeht; während der Behandlung nicht stillen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; die verordnete Therapiedauer genau einhalten.","Alle Medikamente angeben, insbesondere Amiodaron und andere Herzmittel – bei langsamem Puls, Schwindel, Ohnmacht oder Atemnot sofort ärztliche Hilfe holen.","Bei Diabetes oder Einnahme von Gerinnungshemmern (Phenprocoumon) sind während der Therapie häufigere Kontrollen nötig."],"darreichung":["Filmtabletten"]},"sofosbuvir-velpatasvir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-C-Virus an zwei Stellen. Sofosbuvir wird in der Leber zu einem Nukleotid-Analogon aktiviert, das die virale RNA-Polymerase NS5B hemmt und zum Kettenabbruch führt. Velpatasvir blockiert das virale Protein NS5A, das für die Vervielfältigung und den Zusammenbau des Virus nötig ist. Die Kombination wirkt gegen alle Genotypen; Velpatasvir hemmt zudem die Transporter P-Glykoprotein, BCRP und OATP1B.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Müdigkeit","Übelkeit (alle etwa gleich häufig wie unter Placebo)"],"haeufig":["Hautausschlag"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)"],"unbekannt":["Stevens-Johnson-Syndrom","Schwere Bradykardie bei gleichzeitiger Amiodaron-Einnahme","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; vorsichtshalber in der Schwangerschaft nicht anwenden. In Kombination mit Ribavirin kontraindiziert.","stillzeit":"Nicht stillen; der Übergang in die Muttermilch ist beim Menschen nicht bekannt, im Tierversuch wurden die Wirkstoffe in der Milch nachgewiesen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; die Therapie dauert meist 12 Wochen.","Keine Magensäureblocker vom Typ Protonenpumpenhemmer (z. B. Omeprazol, Pantoprazol) ohne ärztliche Rücksprache – sie können die Wirkung stark vermindern.","Bei langsamem Puls, Schwindel oder Ohnmacht (v. a. unter Amiodaron) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"sofosbuvir-velpatasvir-voxilaprevir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-C-Virus an drei Stellen. Sofosbuvir wird in der Leber zu einem Nukleotid-Analogon aktiviert, das die virale RNA-Polymerase NS5B hemmt; Velpatasvir blockiert das Virusprotein NS5A. Voxilaprevir hemmt die virale NS3/4A-Protease, die das Vorläufer-Eiweiss des Virus in funktionsfähige Teile zerschneidet. Voxilaprevir und Velpatasvir hemmen zudem die Transporter OATP1B, P-Glykoprotein und BCRP und erhöhen so die Spiegel mancher anderer Arzneimittel.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall","Übelkeit"],"haeufig":["Bauchschmerzen, Erbrechen","Verminderter Appetit","Hautausschlag","Muskelschmerzen","Bilirubinanstieg im Blut"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Muskelkrämpfe"],"unbekannt":["Stevens-Johnson-Syndrom","Schwere Bradykardie bei gleichzeitiger Amiodaron-Einnahme","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; vorsichtshalber in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht stillen; der Übergang in die Muttermilch ist beim Menschen nicht bekannt, im Tierversuch wurden die Wirkstoffe in der Milch nachgewiesen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Kombinierte Pille, Vaginalring oder Verhütungspflaster mit Ethinylestradiol sind während der Therapie nicht erlaubt – eine andere Verhütung besprechen.","Bei langsamem Puls, Schwindel oder Ohnmacht (v. a. unter Amiodaron) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"solifenacin":{"wirkmechanismus":"Beruhigt den überaktiven Blasenmuskel, sodass die Blase mehr Urin speichern kann. Solifenacin ist ein kompetitiver, bevorzugt am M3-Subtyp wirkender Muskarinrezeptor-Antagonist; M3-Rezeptoren vermitteln die Kontraktion des Blasenmuskels (Detrusor). Der Wirkstoff hat eine lange Halbwertszeit (etwa 45–68 Stunden) und wird hauptsächlich über CYP3A4 in der Leber abgebaut.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Verschwommenes Sehen","Verstopfung","Übelkeit, Verdauungsbeschwerden, Bauchschmerzen"],"gelegentlich":["Harnwegsinfektion, Blasenentzündung","Schläfrigkeit, Geschmacksstörung","Trockene Augen, trockene Nase, trockener Hals","Reflux","Trockene Haut","Erschwertes Wasserlassen","Müdigkeit, Wassereinlagerungen in den Beinen"],"selten":["Schwindel, Kopfschmerzen","Darmverschluss durch Stuhl (Koprostase), Erbrechen","Juckreiz, Hautausschlag","Harnverhalt"],"sehrSelten":["Halluzinationen, Verwirrtheit","Erythema multiforme, Nesselsucht, Angioödem"],"unbekannt":["Anaphylaktische Reaktion","QT-Verlängerung, Torsade de pointes, Vorhofflimmern, Herzrasen","Delir","Glaukom","Darmlähmung (Ileus)","Leberfunktionsstörungen","Hyperkaliämie","Nierenfunktionsstörung","Muskelschwäche"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Erfahrungen vor; nur bei eindeutiger Notwendigkeit.","stillzeit":"Vermeiden – im Tierversuch ging Solifenacin in die Milch über.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten unzerkaut mit Flüssigkeit einnehmen.","Verschwommenes Sehen, Schläfrigkeit oder Müdigkeit können die Fahrtüchtigkeit beeinträchtigen.","Bei Schwellungen von Gesicht, Zunge oder Rachen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"somapacitan":{"wirkmechanismus":"Ersetzt fehlendes Wachstumshormon und muss dank langer Wirkdauer nur einmal pro Woche gespritzt werden. Somapacitan ist ein gentechnisch hergestelltes Wachstumshormon mit einer angehängten Seitenkette, die sich reversibel an Albumin im Blut bindet und so den Abbau verzögert. Es aktiviert den Wachstumshormon-Rezeptor, worauf vor allem in der Leber IGF-1 gebildet wird. Dies fördert bei Kindern das Längenwachstum und beeinflusst bei Erwachsenen Körperzusammensetzung, Fett- und Knochenstoffwechsel.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Gelenk- und Gliederschmerzen","Periphere Ödeme (Wassereinlagerungen)","Müdigkeit, Schwäche","Reaktionen an der Injektionsstelle","Schilddrüsenunterfunktion"],"gelegentlich":["Lipohypertrophie (Fettgewebsverdickung an der Einstichstelle)","Karpaltunnelsyndrom","Juckreiz, Nesselsucht","Gelenk- oder Muskelsteifigkeit"],"unbekannt":["Hüftkopfgleiten bei Kindern","Gutartige Hirndrucksteigerung","Bauchspeicheldrüsenentzündung","Erhöhter Blutzucker","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Einmal pro Woche am gleichen Wochentag unter die Haut spritzen; Einstichstellen wechseln.","Eine vergessene Dosis innerhalb von 3 Tagen nachholen, danach wie gewohnt weiterfahren.","Hinken, Hüft- oder Knieschmerzen sowie starke Kopfschmerzen mit Sehstörungen oder Erbrechen ärztlich abklären.","Regelmässige Kontrollen von IGF-1, Blutzucker und Schilddrüsenwerten."],"darreichung":["Injektionslösung im Fertigpen"]},"somatrogon":{"wirkmechanismus":"Ersetzt fehlendes Wachstumshormon und wird dank langer Wirkdauer nur einmal pro Woche gespritzt. Somatrogon ist ein gentechnisch hergestelltes Wachstumshormon, das mit drei Kopien eines kurzen Peptidstücks aus dem Hormon hCG (C-terminales Peptid) verbunden ist; dies verlängert die Halbwertszeit. Es aktiviert den Wachstumshormon-Rezeptor, worauf IGF-1 gebildet wird, das an den Wachstumsfugen das Längenwachstum fördert.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schmerzen, Rötung, Schwellung, Juckreiz)","Kopfschmerzen","Fieber"],"haeufig":["Schilddrüsenunterfunktion","Gelenk- und Gliederschmerzen","Anämie (Blutarmut)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Allergische Bindehautentzündung"],"unbekannt":["Nebennierenrinden-Insuffizienz","Hüftkopfgleiten (Epiphysiolysis capitis femoris)","Gutartige Hirndrucksteigerung","Bauchspeicheldrüsenentzündung","Fortschreiten einer Skoliose"]},"schwangerschaft":"Keine Daten; Anwendung nicht empfohlen.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Einmal pro Woche am gleichen Wochentag unter die Haut spritzen; Einstichstellen wechseln.","Bei Umstellung von täglichem Wachstumshormon die erste Dosis am Tag nach der letzten täglichen Injektion geben.","Eine vergessene Dosis innerhalb von 3 Tagen nachholen, danach wie gewohnt weiterfahren.","Hinken, Hüft- oder Knieschmerzen sowie starke Kopfschmerzen mit Sehstörungen ärztlich abklären; IGF-1, Blutzucker und Schilddrüse regelmässig kontrollieren."],"darreichung":["Injektionslösung im Fertigpen"]},"somatropin":{"wirkmechanismus":"Ersetzt das körpereigene Wachstumshormon der Hirnanhangdrüse und fördert bei Kindern das Längenwachstum der Knochen. Somatropin ist gentechnisch hergestellt und mit dem menschlichen Hormon identisch. Es bindet an Wachstumshormon-Rezeptoren und regt vor allem in der Leber die Bildung von IGF-1 (insulinähnlicher Wachstumsfaktor 1) an, das an den Wachstumsfugen das Knochenwachstum stimuliert. Zudem fördert es den Eiweissaufbau und den Fettabbau und wirkt dem Insulin entgegen, sodass der Blutzucker steigen kann. Bei Erwachsenen mit Mangel verbessert es Körperzusammensetzung, Knochendichte und Blutfette.","nebenwirkungen":{"sehrHaeufig":["Gelenkschmerzen (v. a. bei Erwachsenen)","Periphere Ödeme (Wassereinlagerungen, v. a. bei Erwachsenen zu Therapiebeginn)"],"haeufig":["Reaktionen an der Einstichstelle (Schmerz, Rötung, Schwellung)","Kopfschmerzen","Parästhesien (Kribbeln, Taubheitsgefühl)","Muskelschmerzen, Muskel- und Gelenksteifigkeit"],"gelegentlich":["Karpaltunnelsyndrom","Hautausschlag, Juckreiz, Nesselsucht","Gynäkomastie (Brustvergrösserung)"],"unbekannt":["Erhöhter Hirndruck (benigne intrakranielle Hypertension) mit Kopfschmerzen, Sehstörungen und Erbrechen","Epiphysiolysis capitis femoris (Abrutschen der Hüftkopf-Wachstumsfuge) bei Kindern","Insulinresistenz, Typ-2-Diabetes","Schilddrüsenunterfunktion","Verminderter Cortisolspiegel","Pankreatitis (Bauchspeicheldrüsenentzündung)","Leukämie (Einzelfälle bei Kindern, Zusammenhang unklar)"]},"schwangerschaft":"Nicht empfohlen; die Erfahrungen sind ungenügend. Tritt eine Schwangerschaft ein, ärztlich über das weitere Vorgehen entscheiden.","stillzeit":"Nur nach ärztlicher Abwägung: es ist nicht bekannt, ob Somatropin in die Muttermilch übergeht; eine Aufnahme durch das Kind ist aber unwahrscheinlich.","hinweise":["Die Einstichstelle bei jeder Injektion wechseln, um Veränderungen des Unterhautfettgewebes zu vermeiden.","Regelmässige Kontrollen von Wachstum, IGF-1, Blutzucker und Schilddrüsenwerten.","Pens und Patronen je nach Präparat im Kühlschrank lagern, nicht einfrieren.","Nicht zur Leistungssteigerung oder als Anti-Aging-Mittel verwenden: Missbrauch ist Doping und gesundheitsschädlich."],"darreichung":["Injektionslösung (Fertigpen, Patrone)","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"sonidegib":{"wirkmechanismus":"Blockiert den Hedgehog-Signalweg, der beim Basalzellkarzinom krankhaft aktiviert ist und das Tumorwachstum antreibt. Sonidegib bindet an das Membranprotein Smoothened (SMO) und hemmt so die nachgeschaltete Aktivierung der GLI-Transkriptionsfaktoren. Da der Signalweg auch für die Entwicklung des Embryos unverzichtbar ist, wirkt Sonidegib stark fruchtschädigend.","nebenwirkungen":{"sehrHaeufig":["Muskelkrämpfe und Muskelschmerzen","Erhöhte Kreatinkinase (Muskelenzym)","Haarausfall","Geschmacksstörungen","Müdigkeit","Übelkeit, Durchfall, Erbrechen","Gewichtsverlust, Appetitlosigkeit","Erhöhte Leberwerte"],"haeufig":["Flüssigkeitsmangel (Dehydratation)","Verdauungsbeschwerden, Sodbrennen","Hautausschlag","Ausbleiben der Regelblutung (Amenorrhö)","Muskelschwäche"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Kontraindiziert – kann zum Tod des Embryos oder zu schweren Fehlbildungen führen. Frauen verhüten bis 20 Monate, Männer verwenden Kondome bis 6 Monate nach der letzten Dosis.","stillzeit":"Kontraindiziert, während der Behandlung und bis 20 Monate nach der letzten Dosis.","hinweise":["Auf nüchternen Magen einnehmen: mindestens 2 Stunden nach und 1 Stunde vor einer Mahlzeit.","Muskelschmerzen, Muskelkrämpfe oder Schwäche sowie dunklen Urin sofort melden.","Kein Blut spenden bis 20 Monate, keine Samenspende bis 6 Monate nach der letzten Dosis."],"darreichung":["Hartkapseln"]},"sorafenib":{"wirkmechanismus":"Hemmt das Wachstum von Tumorzellen und die Bildung neuer Blutgefässe im Tumor. Sorafenib blockiert die RAF-Kinasen (C-RAF, B-RAF) im MAP-Kinase-Signalweg der Tumorzellen sowie Rezeptor-Tyrosinkinasen der Gefässneubildung (VEGFR-1 bis -3, PDGFR-β) und weitere Kinasen wie KIT, FLT3 und RET. So werden Zellteilung und Angiogenese gleichzeitig gehemmt.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Verstopfung","Hand-Fuss-Hautreaktion, Hautausschlag, Juckreiz, Rötung","Haarausfall, trockene Haut","Bluthochdruck","Blutungen (z. B. Magen-Darm, Atemwege, Gehirn)","Müdigkeit, Schmerzen, Fieber, Appetitverlust, Gewichtsabnahme, Gelenkschmerzen","Infektionen, Lymphopenie (Mangel an Lymphozyten)","Hypophosphatämie (tiefes Phosphat), erhöhte Amylase und Lipase"],"haeufig":["Herzinsuffizienz, Herzischämie und Herzinfarkt","Hypothyreose (Schilddrüsenunterfunktion)","Hypokalzämie, Hypokaliämie, Hyponatriämie, Hypoglykämie (Unterzuckerung)","Depression","Mangel an weissen Blutkörperchen und Blutplättchen, Blutarmut","Stomatitis, Schluckbeschwerden, Sodbrennen","Keratoakanthom und Plattenepithelkarzinom der Haut","Nierenversagen, Eiweiss im Urin, periphere Neuropathie, Tinnitus (Ohrgeräusche)"],"gelegentlich":["Hypertensive Krise (Blutdruckentgleisung)","Magen-Darm-Durchbruch (Perforation), Pankreatitis (Bauchspeicheldrüsenentzündung)","Interstitielle Lungenerkrankung","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Erhöhtes Bilirubin, Gelbsucht, Gallenblasenentzündung","Schilddrüsenüberfunktion, Flüssigkeitsmangel","Erythema multiforme, Überempfindlichkeitsreaktionen"],"selten":["QT-Verlängerung","Arzneimittelbedingte Hepatitis (Leberentzündung)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Angioödem (Schwellung von Haut und Schleimhäuten)","Rhabdomyolyse (Muskelzerfall)","Nephrotisches Syndrom"],"unbekannt":["Anaphylaxie (schwerer allergischer Schock)","Aneurysmen und Gefässwandeinrisse (Dissektionen)","Tumorlyse-Syndrom","Enzephalopathie"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Ohne Mahlzeit oder mit einer leichten bis mässig fetthaltigen Mahlzeit einnehmen; bei einer fettreichen Mahlzeit mindestens 1 Stunde vorher oder 2 Stunden nachher.","Blutdruck regelmässig messen; bei Brustschmerzen, Blutungen oder Gelbsucht sofort ärztliche Hilfe holen.","Hände und Füsse pflegen (Feuchtigkeitscreme, druckentlastende Schuhe) – Hautreaktionen früh melden.","Vor Operationen die Behandlung nach ärztlicher Anweisung unterbrechen (Wundheilung)."],"darreichung":["Filmtabletten"]},"sotalol":{"wirkmechanismus":"Stabilisiert den Herzrhythmus und verlangsamt den Puls. Sotalol blockiert nicht-selektiv Beta-1- und Beta-2-Rezeptoren und hemmt zusätzlich Kaliumkanäle (IKr) der Herzmuskelzellen. Dadurch verlängern sich Aktionspotenzial und Refraktärzeit in Vorhöfen und Kammern (Klasse-III-Wirkung), was kreisende Erregungen unterbricht. Die dabei auftretende Verlängerung der QT-Zeit erklärt zugleich das Risiko für Torsade-de-pointes-Arrhythmien.","nebenwirkungen":{"haeufig":["Torsade de pointes und andere neue oder verstärkte Herzrhythmusstörungen","Bradykardie (langsamer Puls), Reizleitungsstörungen","Atemnot, Brustschmerzen, Herzklopfen, Ödeme","Blutdruckabfall, Ohnmacht (Synkope)","Müdigkeit, Schwindel, Kopfschmerzen, Kribbeln","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Geschmacksstörungen","Angst, Verwirrtheit, Stimmungsschwankungen, Schlafstörungen","Seh- und Hörstörungen, Hautausschlag, Muskelkrämpfe, sexuelle Funktionsstörungen"],"unbekannt":["Bronchospasmus (Verkrampfung der Atemwege)","Verschlechterung einer Herzinsuffizienz","Verdeckte Unterzuckerungszeichen bei Diabetes","Verschlechterung von Durchblutungsstörungen und Psoriasis"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach strenger ärztlicher Abwägung; beim Neugeborenen können langsamer Puls, Unterzuckerung und Atemprobleme auftreten.","stillzeit":"Sotalol reichert sich in der Muttermilch an; Stillen wird nicht empfohlen.","hinweise":["Behandlungsbeginn und Dosiserhöhungen nur unter EKG-Kontrolle (QT-Zeit); Nierenfunktion, Kalium und Magnesium regelmässig prüfen lassen.","Bei Durchfall oder Erbrechen ärztlich melden – Elektrolytverluste erhöhen das Risiko gefährlicher Rhythmusstörungen.","Vor der Einnahme neuer Medikamente, auch rezeptfreier, auf QT-Verlängerung prüfen lassen.","Vor den Mahlzeiten einnehmen und nicht abrupt absetzen."],"darreichung":["Tabletten"]},"sotatercept":{"wirkmechanismus":"Greift am krankhaften Umbau der Lungengefässe an, statt diese nur zu erweitern. Sotatercept ist ein Fusionsprotein aus dem Activin-Rezeptor Typ IIA und einem Antikörperteil; es fängt Activine und verwandte Wachstumsfaktoren ab. Dadurch wird das bei PAH gestörte Gleichgewicht zwischen wachstumsfördernden (Activin) und wachstumshemmenden (BMPR2) Signalen wiederhergestellt, die Zellvermehrung in der Gefässwand gebremst und der Widerstand in den Lungengefässen gesenkt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasenbluten","Teleangiektasien (sichtbare erweiterte Äderchen der Haut)","Durchfall","Schwindel","Erhöhtes Hämoglobin (Erythrozytose)","Thrombozytopenie (Mangel an Blutplättchen)"],"haeufig":["Zahnfleischbluten","Hautausschlag, Hautrötung","Blutdruckanstieg"],"unbekannt":["Schwere Blutungen (z. B. im Magen-Darm-Trakt oder im Kopf)"]},"schwangerschaft":"Nicht anwenden – im Tierversuch fruchtschädigend. Vor Beginn Schwangerschaftstest; zuverlässige Verhütung während und bis 4 Monate nach der letzten Dosis.","stillzeit":"Nicht stillen, während der Behandlung und bis 4 Monate nach der letzten Dosis.","hinweise":["Hämoglobin und Thrombozyten werden vor den ersten 5 Dosen und danach regelmässig kontrolliert.","Ungewöhnliche Blutungen, schwarzen Stuhl oder plötzliche starke Kopfschmerzen sofort ärztlich melden.","Wird alle 3 Wochen unter die Haut gespritzt; Selbstinjektion nach Schulung möglich."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (unter die Haut)"]},"sotorasib":{"wirkmechanismus":"Blockiert gezielt ein verändertes Wachstumssignal-Eiweiss in Tumorzellen. Sotorasib bindet kovalent und irreversibel an das Cystein der mutierten KRAS-G12C-Variante und hält das Protein in seinem inaktiven, GDP-gebundenen Zustand fest. Dadurch wird die nachgeschaltete Signalübertragung (u. a. über den MAPK-Weg) unterbrochen, die Zellteilung gehemmt und der Zelltod der Tumorzellen gefördert. Nicht mutiertes KRAS wird kaum beeinflusst.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Erhöhte Leberwerte (ALT, AST)","Müdigkeit, Fieber","Gelenk- und Rückenschmerzen","Husten, Atemnot","Anämie (Blutarmut)"],"haeufig":["Erhöhte alkalische Phosphatase und Bilirubin"],"gelegentlich":["Interstitielle Lungenerkrankung/Pneumonitis (nicht infektiöse Lungenentzündung)"],"unbekannt":["Arzneimittelbedingte Leberschädigung (Hepatitis)"]},"schwangerschaft":"Nicht empfohlen (keine Erfahrungen). Frauen im gebärfähigen Alter sollen zuverlässig verhüten; hormonale Verhütung kann unzureichend wirken.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit einnehmen, mit oder ohne Essen; Tabletten ganz schlucken.","Säureblocker (PPI, H2-Blocker) meiden; Antazida nur mit zeitlichem Abstand.","Leberwerte werden regelmässig kontrolliert; neuen Husten oder Atemnot sofort melden."],"darreichung":["Filmtabletten"]},"sparsentan":{"wirkmechanismus":"Senkt die Eiweissausscheidung im Urin und schützt die Niere, indem es die Wirkung von zwei gefässverengenden Hormonen blockiert. Sparsentan ist ein Antagonist sowohl am Endothelin-Typ-A-Rezeptor als auch am Angiotensin-II-Typ-1-Rezeptor (AT1). Dadurch sinkt der Druck in den Nierenkörperchen (Glomeruli), und entzündliche und vernarbende Vorgänge, die Endothelin und Angiotensin II in der Niere fördern, werden gebremst. Zusätzlich senkt es den Blutdruck.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium)","Hypotonie (tiefer Blutdruck), auch beim Aufstehen","Periphere Ödeme (Wassereinlagerungen)","Schwindel"],"haeufig":["Kopfschmerzen","Müdigkeit","Anämie (Blutarmut)","Akute Nierenschädigung, Anstieg des Kreatinins","Erhöhte Leberwerte (Transaminasen)"],"unbekannt":["Arzneimittelbedingte Leberschädigung"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend wie andere Endothelin-Rezeptor-Antagonisten und RAAS-Hemmer). Vor Beginn Schwangerschaft ausschliessen und zuverlässig verhüten.","stillzeit":"Nicht stillen, da ein Risiko für den Säugling nicht ausgeschlossen werden kann.","hinweise":["Leberwerte vor Beginn, im ersten Jahr monatlich und danach alle 3 Monate kontrollieren; Gelbsucht, dunklen Urin, Übelkeit oder Oberbauchschmerzen sofort melden.","ACE-Hemmer, Sartane und Aliskiren vor Beginn absetzen.","Blutdruck, Kalium und Nierenwerte regelmässig kontrollieren; zu Beginn Vorsicht beim Aufstehen und Autofahren (Schwindel).","Frauen im gebärfähigen Alter: zuverlässig verhüten und Schwangerschaftstests nach ärztlicher Anweisung durchführen."],"darreichung":["Filmtabletten"]},"spesolimab":{"wirkmechanismus":"Bremst die Entzündung, die bei der pustulösen Psoriasis zu grossflächigen Eiterbläschen, Fieber und Krankheitsgefühl führt. Spesolimab ist ein humanisierter monoklonaler IgG1-Antikörper, der an den Interleukin-36-Rezeptor bindet und dessen Aktivierung durch die Botenstoffe IL-36α, IL-36β und IL-36γ verhindert. Damit wird ein Entzündungssignalweg gehemmt, der bei GPP – oft wegen erblicher Veränderungen des natürlichen Gegenspielers IL-36Ra – überaktiv ist.","nebenwirkungen":{"sehrHaeufig":["Infektionen (vor allem Harnwegs- und Atemwegsinfekte)"],"haeufig":["Müdigkeit","Juckreiz","Reaktionen an der Infusions- bzw. Einstichstelle"],"unbekannt":["Überempfindlichkeits- und Infusionsreaktionen","DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber vermeiden und nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob Spesolimab in die Muttermilch übergeht; nur nach ärztlicher Abwägung.","hinweise":["Wird im Spital als Infusion gegeben; bei anhaltendem Schub kann nach einer Woche eine zweite Infusion folgen.","Bei Fieber, Husten oder Brennen beim Wasserlösen in den Wochen nach der Infusion ärztlich abklären lassen.","Keine Lebendimpfungen während und bis mindestens 16 Wochen nach der Behandlung."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"spironolacton":{"wirkmechanismus":"Hemmt die Wirkung des Hormons Aldosteron in der Niere; dadurch werden mehr Salz und Wasser ausgeschieden, Kalium dagegen zurückgehalten. Spironolacton und seine aktiven Abbauprodukte (u. a. Canrenon) blockieren kompetitiv den Mineralokortikoid-Rezeptor im spätdistalen Tubulus und im Sammelrohr. Bei Herzinsuffizienz wirkt es zusätzlich den schädlichen Aldosteronwirkungen auf Herz und Gefässe (Umbau, Vernarbung) entgegen. Es bindet auch an Androgen- und Progesteronrezeptoren, was hormonelle Nebenwirkungen wie eine Brustvergrösserung bei Männern erklärt. Die volle harntreibende Wirkung entwickelt sich erst nach 2–3 Tagen.","nebenwirkungen":{"haeufig":["Hyperkaliämie (erhöhtes Kalium)","Gynäkomastie (Brustvergrösserung beim Mann), Brustschmerzen","Verwirrtheit, Schwindel","Übelkeit","Juckreiz, Hautausschlag","Muskelkrämpfe","Akute Nierenschädigung","Unwohlsein"],"unbekannt":["Agranulozytose, Leukopenie, Thrombozytopenie","Elektrolytstörungen wie Natriummangel","Libidoveränderungen, Menstruationsstörungen","Leberfunktionsstörungen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Pemphigoid","Haarausfall, vermehrte Körperbehaarung, Nesselsucht","Gutartige Knoten in der Brust beim Mann","Magen-Darm-Beschwerden"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: im Tierversuch führte Spironolacton zu einer Verweiblichung männlicher Nachkommen.","stillzeit":"Ein Abbauprodukt (Canrenon) geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Kalium und Nierenwerte zu Beginn, nach Dosisänderungen und danach regelmässig kontrollieren lassen.","Keine Kaliumpräparate oder kaliumhaltigen Salzersatzmittel ohne ärztliche Anordnung verwenden; Schmerzmittel wie Ibuprofen oder Diclofenac meiden.","Bei Durchfall, Erbrechen oder Fieber mit Flüssigkeitsverlust ärztlichen Rat einholen (Gefahr von Nierenversagen und Hyperkaliämie).","Mit einer Mahlzeit einnehmen."],"darreichung":["Filmtabletten"]},"spurenelemente-parenteral":{"wirkmechanismus":"Ersetzt Spurenelemente, die bei künstlicher Ernährung über die Vene sonst fehlen würden. Je nach Präparat enthalten die Lösungen Zink, Kupfer, Mangan, Selen, Jod, Fluor, Chrom, Molybdän und Eisen. Diese Elemente sind Bausteine zahlreicher Enzyme und Hormone (z. B. Schilddrüsenhormone, Glutathionperoxidase) und für Immunabwehr, Blutbildung, Wundheilung und Stoffwechsel nötig.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen","Anreicherung von Mangan oder Kupfer bei langfristiger Gabe, besonders bei Leber- oder Gallenproblemen"]},"schwangerschaft":"Bei bedarfsgerechter Zufuhr im Rahmen einer parenteralen Ernährung anwendbar.","stillzeit":"Bei bedarfsgerechter Zufuhr anwendbar.","hinweise":["Nur verdünnt als Zusatz zu Infusions- oder Ernährungslösungen geben.","Bei langfristiger parenteraler Ernährung Spurenelement-Spiegel und Leberwerte regelmässig kontrollieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"stiripentol":{"wirkmechanismus":"Verstärkt die beruhigende Wirkung des Botenstoffs GABA im Gehirn. Stiripentol wirkt als positiver Modulator am GABA-A-Rezeptor und erhöht zusätzlich die GABA-Konzentration. Ein wesentlicher Teil der Wirkung beruht darauf, dass es den Abbau anderer Antiepileptika – vor allem von Clobazam und dessen aktivem Abbauprodukt Norclobazam – über die Leberenzyme CYP2C19, CYP3A4 und CYP1A2 hemmt.","nebenwirkungen":{"sehrHaeufig":["Appetitlosigkeit, Gewichtsverlust","Schlaflosigkeit","Schläfrigkeit","Gangunsicherheit (Ataxie), verminderte Muskelspannung, Dystonie (Muskelverkrampfungen)"],"haeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Aggressivität, Reizbarkeit, Verhaltensstörungen, Übererregbarkeit","Übermässige Bewegungsaktivität (Hyperkinesie)","Übelkeit, Erbrechen","Erhöhte Gamma-GT (Leberwert)"],"gelegentlich":["Doppelbilder","Lichtempfindlichkeit der Haut, Hautausschlag, Nesselsucht","Müdigkeit"],"selten":["Verminderte Blutplättchen (Thrombozytopenie)","Veränderte Leberwerte"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach sorgfältiger ärztlicher Abwägung. Eine wirksame antiepileptische Behandlung nicht eigenmächtig absetzen.","stillzeit":"Nicht bekannt, ob Stiripentol in die Muttermilch übergeht; Stillen wird nicht empfohlen.","hinweise":["Zu einer Mahlzeit einnehmen, aber nicht mit Milch oder Milchprodukten, kohlensäurehaltigen Getränken, Fruchtsäften oder koffeinhaltigen Lebensmitteln (Cola, Kaffee, Tee, Schokolade).","Blutbild und Leberwerte vor Beginn und alle 6 Monate kontrollieren.","Gewicht und Wachstum des Kindes regelmässig kontrollieren."],"darreichung":["Kapseln","Pulver zur Herstellung einer Suspension zum Einnehmen"]},"sucralfat":{"wirkmechanismus":"Legt sich wie ein Schutzfilm über geschädigte Stellen der Magen- und Darmschleimhaut. Im sauren Magen bildet Sucralfat eine zähe, haftende Masse, die sich bevorzugt an die eiweissreichen Geschwürsflächen bindet und sie vor Säure, Pepsin und Gallensäuren schützt. Zusätzlich bindet es Pepsin und Gallensäuren und fördert schleimhauteigene Schutzfaktoren wie Prostaglandine, Schleim und Bicarbonat. Die Magensäure wird kaum neutralisiert; der Wirkstoff selbst wird praktisch nicht aufgenommen, kleine Mengen Aluminium jedoch schon.","nebenwirkungen":{"haeufig":["Obstipation (Verstopfung)"],"gelegentlich":["Mundtrockenheit","Übelkeit"],"selten":["Hautausschlag, Juckreiz"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Erbrechen, Völlegefühl, Blähungen","Bezoarbildung (Klumpen im Magen)","Blutzuckeranstieg bei Diabetes","Aluminiumanreicherung mit Knochenerweichung oder Hirnschädigung (Enzephalopathie) bei Niereninsuffizienz"]},"schwangerschaft":"Da praktisch nichts aufgenommen wird, ist die Anwendung nach ärztlicher Abwägung möglich; eine Langzeitanwendung meiden.","stillzeit":"Nach ärztlicher Abwägung möglich; es ist kein relevanter Übergang in die Muttermilch zu erwarten.","hinweise":["Auf nüchternen Magen einnehmen, vor den Mahlzeiten und vor dem Schlafengehen.","Andere Arzneimittel mindestens 2 Stunden vorher einnehmen.","Bei Nierenschwäche nicht ohne ärztliche Kontrolle über längere Zeit einnehmen."],"darreichung":["Tabletten","Suspension zum Einnehmen"]},"sufentanil":{"wirkmechanismus":"Sehr starkes Schmerzmittel, etwa 5- bis 10-mal stärker als Fentanyl. Sufentanil ist ein hochselektiver Agonist am µ-Opioidrezeptor und hemmt die Schmerzweiterleitung in Rückenmark und Gehirn. Es ist sehr fettlöslich, wirkt rasch und bei periduraler Gabe zusammen mit Lokalanästhetika direkt im Rückenmarksbereich. Der Abbau erfolgt in der Leber über CYP3A4.","nebenwirkungen":{"sehrHaeufig":["Sedierung (Schläfrigkeit), besonders bei periduraler Gabe","Juckreiz"],"haeufig":["Schwindel, Kopfschmerzen","Übelkeit, Erbrechen","Tachykardie (Herzrasen)","Blutdruckanstieg oder -abfall","Muskelzuckungen","Harnverhalt","Fieber","Zittern beim Neugeborenen nach Gabe unter der Geburt"],"unbekannt":["Atemdepression bis Atemstillstand","Muskelsteifigkeit (auch der Brustwand)","Bradykardie, Herzrhythmusstörungen, Herzstillstand","Bronchospasmus, Laryngospasmus","Krampfanfälle, Myoklonien (Muskelzuckungen)","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit. Intravenös unter der Geburt kontraindiziert (Atemdepression beim Neugeborenen); peridural zusammen mit einem Lokalanästhetikum zur Geburtsanalgesie möglich.","stillzeit":"Sufentanil geht in die Muttermilch über; nach intravenöser Gabe 24 Stunden lang nicht stillen.","hinweise":["Wird nur durch Anästhesiefachpersonen mit Überwachung und Beatmungsmöglichkeit verabreicht; Gegenmittel ist Naloxon.","Antidepressiva (v. a. MAO-Hemmer), Pilz-, HIV- und Antibiotika-Behandlungen vor dem Eingriff angeben.","Nach dem Eingriff mindestens 24 Stunden kein Fahrzeug lenken, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Injektionslösung"]},"sugammadex":{"wirkmechanismus":"Hebt die Muskelerschlaffung nach einer Narkose auf, indem es das Muskelrelaxans im Blut abfängt. Sugammadex ist ein modifiziertes Gamma-Cyclodextrin, das Rocuronium und Vecuronium in seinem Ring einschliesst und einen sehr festen Komplex bildet. Dadurch sinkt die freie Menge des Relaxans an der motorischen Endplatte, und die Muskelkraft kehrt innert weniger Minuten zurück – auch nach tiefer Blockade. Der Komplex wird unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Komplikationen beim Erwachen aus der Narkose (Bewegungen, Husten, Pressen gegen den Beatmungsschlauch)","Atemwegskomplikationen während der Narkose"],"gelegentlich":["Überempfindlichkeitsreaktionen (Hautrötung, Ausschlag) bis zur Anaphylaxie","Wiederkehrende Muskelerschlaffung (Recurarisierung)"],"unbekannt":["Ausgeprägte Bradykardie (verlangsamter Puls) bis zum Herzstillstand","Bronchospasmus (Verkrampfung der Atemwege)","Blutdruckabfall während des Eingriffs"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; nur nach sorgfältiger Abwägung anwenden. Tierversuche zeigen keine schädlichen Wirkungen.","stillzeit":"Ob Sugammadex in die Muttermilch übergeht, ist nicht bekannt; da es über den Darm kaum aufgenommen wird, ist nach einer Einzeldosis keine Wirkung beim Säugling zu erwarten.","hinweise":["Frauen mit Pille, Ring, Implantat oder Hormonspirale: während 7 Tagen nach der Narkose zusätzlich mit Kondom verhüten.","Wird nur von Anästhesie-Fachpersonen angewendet; Atmung und Kreislauf werden nach der Gabe überwacht."],"darreichung":["Injektionslösung"]},"sulfamethoxazol-trimethoprim":{"wirkmechanismus":"Hemmt die Vermehrung von Bakterien, indem es ihre Folsäure-Herstellung an zwei Stellen blockiert. Sulfamethoxazol verdrängt die Para-Aminobenzoesäure und hemmt die Dihydropteroat-Synthase; Trimethoprim hemmt die bakterielle Dihydrofolat-Reduktase. Ohne Folsäure können die Bakterien keine Erbsubstanz bilden; die doppelte Blockade wirkt synergistisch und oft bakterizid. Trimethoprim hemmt in der Niere zudem Natriumkanäle, was das Kalium im Blut erhöhen kann.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium), vor allem bei hohen Dosen"],"haeufig":["Übelkeit, Durchfall","Hautausschlag","Kopfschmerzen","Pilzinfektionen (Candida)"],"gelegentlich":["Erbrechen"],"sehrSelten":["Blutbildschäden: Agranulozytose, megaloblastäre oder aplastische Anämie, Thrombozytopenie, Panzytopenie","Hämolytische Anämie (Blutzerfall), besonders bei G6PD-Mangel","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Lichtempfindlichkeit","Anaphylaxie, Angioödem, Arzneimittelfieber","Hepatitis mit Gelbsucht, Lebernekrose","Hyponatriämie (Natriummangel), Hypoglykämie (Unterzuckerung)","Aseptische Meningitis, Krampfanfälle, Halluzinationen","Interstitielle Nephritis, Nierenfunktionsstörung, Kristallurie; Pankreatitis; Lungeninfiltrate"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Schwere Lungenschädigung bis zum akuten Lungenversagen (ARDS)","Hämophagozytische Lymphohistiozytose (lebensbedrohliche Überaktivierung des Immunsystems)","Clostridioides-difficile-Kolitis"]},"schwangerschaft":"Trimethoprim ist ein Folsäure-Antagonist: im 1. Drittel nur bei zwingender Indikation (mit Folsäure-Ergänzung). Kurz vor der Geburt vermeiden, weil Sulfonamide beim Neugeborenen einen Kernikterus begünstigen können.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Abwägung; vermeiden bei Früh- oder Neugeborenen, bei Gelbsucht oder G6PD-Mangel des Kindes.","hinweise":["Reichlich trinken, um Kristalle im Urin zu vermeiden; starke Sonne meiden.","Bei Hautausschlag, Blasen, Fieber, Halsschmerzen oder Blutungszeichen sofort absetzen und ärztlichen Rat holen.","Bei längerer Einnahme Blutbild, Kalium und Nierenwerte kontrollieren lassen."],"darreichung":["Tabletten","Suspension zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung"]},"sulfasalazin":{"wirkmechanismus":"Hemmt Entzündungen im Darm und in den Gelenken. Sulfasalazin ist eine Vorstufe (Prodrug): Darmbakterien spalten es im Dickdarm in 5-Aminosalicylsäure (Mesalazin) und Sulfapyridin. Mesalazin wirkt örtlich an der Darmschleimhaut entzündungshemmend (Hemmung von Prostaglandinen und Leukotrienen, Abfangen von Sauerstoffradikalen); das ins Blut aufgenommene Sulfapyridin trägt vermutlich zur Wirkung bei Rheuma bei und verursacht den Grossteil der Nebenwirkungen. Zusätzlich dämpft Sulfasalazin die Aktivierung von Immunzellen (u. a. über NF-κB).","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Magenbeschwerden"],"haeufig":["Appetitlosigkeit, Erbrechen, Bauchschmerzen, Durchfall","Kopfschmerzen, Schwindel, Geschmacksstörungen","Ohrensausen (Tinnitus)","Husten","Juckreiz","Gelenkschmerzen","Fieber","Leukopenie (Mangel an weissen Blutkörperchen), Eiweiss im Urin"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Depression","Atemnot","Haarausfall","Nesselsucht","Erhöhte Leberwerte"],"unbekannt":["Agranulozytose, aplastische Anämie, Panzytopenie (schwere Blutbildschäden); megaloblastäre oder hämolytische Anämie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Hepatitis bis Leberversagen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenschäden (Lungeninfiltrate, fibrosierende Alveolitis)","Nierenentzündung, nephrotisches Syndrom","Herzbeutel- oder Herzmuskelentzündung","Vorübergehend verminderte Spermienzahl (Oligospermie)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden; wegen der verminderten Folsäureaufnahme wird eine zusätzliche Folsäure-Einnahme empfohlen.","stillzeit":"Sulfapyridin geht in die Muttermilch über; bei gesunden, reifen Säuglingen meist vertretbar. Vorsicht bei Frühgeborenen, Neugeborenengelbsucht oder G6PD-Mangel; blutiger Durchfall beim Säugling wurde beschrieben.","hinweise":["Blutbild, Leber- und Nierenwerte regelmässig kontrollieren lassen; bei Halsschmerzen, Fieber, Blässe oder Blutungen sofort ärztlich melden.","Urin und Haut können sich gelb-orange verfärben; weiche Kontaktlinsen können sich dauerhaft verfärben.","Tabletten nach dem Essen mit reichlich Flüssigkeit einnehmen; magensaftresistente Tabletten nicht zerkauen."],"darreichung":["Tabletten","Magensaftresistente Tabletten"]},"sulpirid":{"wirkmechanismus":"Mildert psychotische Symptome; in niedriger Dosis wirkt es eher antriebssteigernd. Sulpirid blockiert selektiv Dopamin-D2- und D3-Rezeptoren, kaum aber Histamin-, Muskarin- oder Alpha-Rezeptoren. In niedriger Dosis werden vorwiegend präsynaptische Rezeptoren blockiert, was die Dopaminfreisetzung steigert; höhere Dosen wirken antipsychotisch. Die Blockade in der Hypophyse erhöht das Prolaktin deutlich. Sulpirid wird unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Erhöhter Prolaktinspiegel","Milchfluss (Galaktorrhö), Brustschmerzen","Schläfrigkeit, Schlaflosigkeit","Extrapyramidale Störungen (Zittern, Muskelsteifigkeit, Sitzunruhe)","Gewichtszunahme"],"gelegentlich":["Brustvergrösserung, Ausbleiben der Regel, Orgasmus- und Erektionsstörungen","Dyskinesien, Dystonie (Muskelverkrampfungen)","Vermehrter Speichelfluss","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Hautausschlag"],"selten":["Blickkrämpfe","Ventrikuläre Herzrhythmusstörungen"],"unbekannt":["QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung), plötzlicher Herztod","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Krampfanfälle","Spätdyskinesien (unwillkürliche Bewegungen)","Blutbildveränderungen bis Agranulozytose","Hyponatriämie (Natriummangel)","Venöse Thromboembolien (Blutgerinnsel)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Geht in die Muttermilch über; Stillen wird nicht empfohlen.","hinweise":["Kann die Reaktionsfähigkeit beeinträchtigen – Vorsicht beim Autofahren, Alkohol meiden.","Milchfluss, Brustspannen, Ausbleiben der Regel oder Potenzstörungen ärztlich melden (Prolaktinanstieg).","Bei Fieber mit Muskelsteifigkeit und Verwirrtheit sofort ärztliche Hilfe holen (malignes neuroleptisches Syndrom)."],"darreichung":["Kapseln","Tabletten"]},"sulproston":{"wirkmechanismus":"Bringt die Gebärmutter kräftig zum Zusammenziehen und stillt so Blutungen nach der Geburt. Sulproston ist ein synthetischer Abkömmling von Prostaglandin E2, der vor allem an EP3- und EP1-Rezeptoren der Gebärmuttermuskulatur bindet und starke, anhaltende Kontraktionen auslöst. Zusätzlich erweicht es den Gebärmutterhals. Die Wirkung auf die glatte Muskulatur von Gefässen und Bronchien erklärt die Risiken für Herz, Kreislauf und Atemwege.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Durchfall","Bauch- und Unterleibskrämpfe"],"unbekannt":["Fieber, Schüttelfrost","Bronchospasmus (Verkrampfung der Atemwege), Atemnot","Blutdruckabfall oder Blutdruckanstieg","Langsamer Puls und Herzrhythmusstörungen","Verkrampfung der Herzkranzgefässe (Koronarspasmus), Herzinfarkt, Herzstillstand","Lungenödem (Wasser in der Lunge)","Gebärmutterriss (bei Anwendung zum Schwangerschaftsabbruch)"]},"schwangerschaft":"Bei einer Schwangerschaft, die ausgetragen werden soll, kontraindiziert. Anwendung nur zum medizinisch angezeigten Schwangerschaftsabbruch, bei abgestorbener Frucht oder nach der Geburt.","stillzeit":"Keine ausreichenden Daten zum Übergang in die Muttermilch; Stillen nur nach ärztlicher Rücksprache.","hinweise":["Nur im Spital unter laufender Kontrolle von Blutdruck, Puls, EKG und Atmung.","Brustschmerzen, Atemnot oder Herzklopfen während der Infusion sofort melden – die Infusion wird dann abgebrochen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"sultiam":{"wirkmechanismus":"Dämpft die Erregbarkeit von Nervenzellen im Gehirn. Sultiam hemmt das Enzym Carboanhydrase; die dadurch leicht saure Stoffwechsellage in und um die Nervenzellen senkt deren Erregbarkeit. Der genaue Wirkmechanismus bei der Rolando-Epilepsie ist nicht vollständig geklärt.","nebenwirkungen":{"haeufig":["Kribbeln oder Taubheitsgefühl in Händen, Füssen und im Gesicht (Parästhesien)","Beschleunigte oder vertiefte Atmung, Atemnot","Magenbeschwerden, Übelkeit, Appetitlosigkeit","Gewichtsabnahme","Kopfschmerzen, Schwindel","Doppelbilder"],"unbekannt":["Psychische Veränderungen (z. B. Halluzinationen, Angst, Antriebsarmut)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, Lyell-Syndrom)","Akutes Nierenversagen","Metabolische Azidose (Übersäuerung des Blutes)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Nicht anwenden, ausser auf ausdrückliche ärztliche Verordnung nach sorgfältiger Abwägung.","stillzeit":"Keine ausreichenden Daten; Stillen wird nicht empfohlen.","hinweise":["Kribbeln und eine schnellere, tiefere Atmung sind zu Beginn häufig; bei Atemnot ärztlich abklären.","Bei Hautausschlag sofort ärztlich abklären.","Nicht abrupt absetzen.","Kann das Reaktionsvermögen beeinträchtigen (Strassenverkehr, Velofahren)."],"darreichung":["Filmtabletten"]},"sumatriptan":{"wirkmechanismus":"Lindert den Migränekopfschmerz, indem es erweiterte Blutgefässe im Kopf verengt und die Freisetzung entzündlicher Botenstoffe bremst. Sumatriptan ist ein selektiver Agonist an Serotonin-5-HT1B- und -5-HT1D-Rezeptoren: Über 5-HT1B verengt es erweiterte kraniale Gefässe, über 5-HT1D hemmt es die Ausschüttung von Neuropeptiden wie CGRP aus den Endigungen des Trigeminusnervs. Es wirkt nur im Anfall, nicht vorbeugend. Der Abbau erfolgt hauptsächlich über die Monoaminoxidase A (MAO-A).","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle (Injektion); auch Brennen, Rötung, Schwellung oder Bluterguss"],"haeufig":["Schwindel, Schläfrigkeit","Kribbeln oder Taubheitsgefühl (Parästhesien), Hitze- oder Kältegefühl","Vorübergehender Blutdruckanstieg, Gesichtsrötung (Flush)","Atemnot (Dyspnoe)","Übelkeit, Erbrechen","Schwere-, Druck- oder Engegefühl in Brust, Hals oder Gliedern","Müdigkeit, Schwächegefühl, Muskelschmerzen"],"sehrSelten":["Leichte Veränderungen der Leberwerte"],"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Koronare Gefässkrämpfe, Angina pectoris, Herzinfarkt","Herzrhythmusstörungen (Herzrasen, verlangsamter Puls)","Krampfanfälle, Zittern, Bewegungsstörungen","Sehstörungen (Flimmern, Doppelbilder, vorübergehender Sehverlust)","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)","Blutdruckabfall, Raynaud-Phänomen (weisse Finger)","Durchfall"]},"schwangerschaft":"Daten aus Registern mit über 1000 Schwangerschaften zeigen kein erhöhtes Fehlbildungsrisiko; Anwendung nur nach ärztlicher Abwägung.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nach der Anwendung 12 Stunden nicht stillen (Milch abpumpen und verwerfen).","hinweise":["Erst bei Beginn des Kopfschmerzes anwenden, nicht vorbeugend während der Aura; hilft die erste Dosis nicht, bei derselben Attacke keine zweite Dosis nehmen.","Bei Brustschmerzen oder starkem Engegefühl nach der Anwendung ärztlich abklären lassen.","Akutmittel gegen Migräne an höchstens 10 Tagen pro Monat verwenden, sonst droht Kopfschmerz durch Medikamentenübergebrauch.","Kann Schläfrigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten","Nasenspray","Injektionslösung (Fertigspritze/Autoinjektor)"]},"sunitinib":{"wirkmechanismus":"Hemmt das Wachstum von Tumoren und die Bildung neuer Blutgefässe, die den Tumor versorgen. Sunitinib blockiert zahlreiche Rezeptor-Tyrosinkinasen, darunter die VEGF-Rezeptoren 1–3, die PDGF-Rezeptoren α und β, KIT, FLT3, CSF-1R und RET. Dadurch werden Gefässneubildung (Angiogenese) und Wachstumssignale der Tumorzellen unterbrochen. Der Hauptmetabolit N-Desethyl-Sunitinib (SU12662) ist gleich wirksam und trägt wesentlich zur Wirkung bei.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Schwäche, Ödeme, Fieber","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Stomatitis (Entzündung der Mundschleimhaut), Geschmacksstörungen, Appetitverlust","Bluthochdruck","Hand-Fuss-Syndrom, Gelbfärbung der Haut, Veränderung der Haarfarbe, Hautausschlag","Hypothyreose (Schilddrüsenunterfunktion)","Blutarmut, Mangel an Blutplättchen und weissen Blutkörperchen","Nasenbluten, Kopfschmerzen, Schwindel"],"haeufig":["Infektionen","Abnahme der Herzpumpfunktion, Durchblutungsstörungen des Herzmuskels (Myokardischämie)","Venenthrombose und Lungenembolie","Hypoglykämie (Unterzuckerung), Flüssigkeitsmangel","Magen-Darm-Blutungen","Eiweiss im Urin (Proteinurie), Nierenversagen","Periphere Neuropathie (Kribbeln, Taubheit), Schwellungen um die Augen"],"gelegentlich":["Herzinsuffizienz, Herzinfarkt, Kardiomyopathie","QT-Verlängerung im EKG","Leberversagen","Magen-Darm-Durchbruch (Perforation), Pankreatitis (Bauchspeicheldrüsenentzündung)","Hirnblutung, Schlaganfall","Kiefernekrose (Absterben von Kieferknochen)","Schilddrüsenüberfunktion"],"selten":["Torsade de pointes (lebensbedrohliche Herzrhythmusstörung)","Thrombotische Mikroangiopathie (Gerinnsel in kleinsten Gefässen)","Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Krampfanfälle, Sehstörungen)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Rhabdomyolyse (Muskelzerfall)","Tumorlyse-Syndrom, nephrotisches Syndrom"],"unbekannt":["Aneurysmen und Gefässwandeinrisse (Dissektionen)","Nekrotisierende Fasziitis (schwere Weichteilinfektion)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit – kann das ungeborene Kind schädigen. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einnahme meist in Zyklen (z. B. 4 Wochen Einnahme, 2 Wochen Pause), mit oder ohne Mahlzeit; keine Grapefruit, kein Johanniskraut.","Blutdruck regelmässig messen; Blutbild, Leber- und Schilddrüsenwerte werden regelmässig kontrolliert.","Vor Operationen und Zahnbehandlungen auf die Einnahme hinweisen (Wundheilung, Kiefernekrose).","Eine gelbliche Verfärbung von Haut und Urin durch den Wirkstoff ist harmlos; gelbe Augen oder dunkler Urin mit Oberbauchschmerzen können aber auf einen Leberschaden hinweisen – sofort melden."],"darreichung":["Hartkapseln"]},"sutimlimab":{"wirkmechanismus":"Verhindert, dass Kälte-Autoantikörper die roten Blutkörperchen über das Komplementsystem zum Abbau markieren. Sutimlimab ist ein humanisierter monoklonaler IgG4-Antikörper gegen die Serinprotease C1s, das Startenzym des klassischen Komplementwegs. Dadurch werden C4b und C3b nicht mehr auf den roten Blutkörperchen abgelagert, die sonst vor allem in der Leber abgebaut würden (extravaskuläre Hämolyse). Der Lektin- und der alternative Komplementweg bleiben erhalten.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Bluthochdruck","Infekte der Atem- und Harnwege","Akrozyanose (Blaufärbung von Fingern und Zehen), Raynaud-Syndrom"],"haeufig":["Übelkeit, Bauchschmerzen","Schwindel","Periphere Ödeme (Wassereinlagerungen)","Fieber","Infusionsreaktionen","Herpesinfektionen"],"unbekannt":["Schwere Infektionen mit bekapselten Bakterien"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das Risiko klar überwiegt; als Antikörper kann Sutimlimab die Plazenta passieren.","stillzeit":"Keine Daten; über Stillen ist ärztlich zu entscheiden.","hinweise":["Impfungen gegen Meningokokken und Pneumokokken vor Beginn abschliessen.","Fieber oder andere Infektzeichen sofort ärztlich melden.","Infusionstermine einhalten; nach dem Absetzen kann der Blutzerfall zurückkehren."],"darreichung":["Infusionslösung"]},"suxamethonium":{"wirkmechanismus":"Erschlafft die Skelettmuskulatur für wenige Minuten, damit z. B. ein Beatmungsschlauch eingeführt werden kann. Suxamethonium besetzt wie Acetylcholin die nikotinischen Rezeptoren an der motorischen Endplatte und löst eine anhaltende Depolarisation aus, sichtbar als kurze Muskelzuckungen (Faszikulationen); danach ist die Muskelfaser vorübergehend nicht mehr erregbar. Es wird rasch durch die Plasmacholinesterase (Pseudocholinesterase) abgebaut: Die Wirkung tritt innerhalb einer Minute ein und hält etwa 5–10 Minuten an.","nebenwirkungen":{"sehrHaeufig":["Muskelzuckungen (Faszikulationen) zu Beginn","Muskelschmerzen nach der Narkose","Erhöhter Augeninnendruck"],"haeufig":["Bradykardie (langsamer Puls) oder Tachykardie (Herzrasen)","Hautrötung, Hautausschlag","Hyperkaliämie (erhöhtes Kalium)","Myoglobinämie und Myoglobinurie (Muskelfarbstoff in Blut und Urin)","Erhöhter Druck im Magen"],"selten":["Herzrhythmusstörungen bis Herzstillstand","Bronchospasmus (Verkrampfung der Atemwege)","Verlängerte Atemlähmung (Apnoe)","Kieferklemme (Trismus)"],"sehrSelten":["Maligne Hyperthermie (lebensbedrohliche Überwärmung mit Muskelstarre)","Anaphylaxie (schwere allergische Reaktion)","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden, z. B. beim Kaiserschnitt; nur geringe Mengen passieren die Plazenta. Die Plasmacholinesterase ist in der Schwangerschaft vermindert, die Wirkung kann daher verlängert sein.","stillzeit":"Wird sehr rasch abgebaut; ein Risiko für den Säugling ist nicht zu erwarten. Stillen nach der Narkose in Absprache mit dem Behandlungsteam.","hinweise":["Wird nur von Anästhesie-Fachpersonen mit Beatmungsmöglichkeit angewendet.","Vor einer Narkose maligne Hyperthermie, Muskelerkrankungen oder ungewöhnlich lange Narkosewirkung in der Familie angeben.","Muskelkater-artige Schmerzen nach der Narkose sind häufig und klingen nach wenigen Tagen ab."],"darreichung":["Injektionslösung"]}});
